// ── RENDER ────────────────────────────────────────────────────────────────────
const esc = v => String(v === null || v === undefined ? '' : v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const escAttr = v => esc(v).replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const score = v => { const n=parseInt(v === null || v === undefined ? 0 : v); const cls=n>=80?'high':n>=60?'mid':'low'; return `<span class="score ${cls}">${n}%</span>`; };
const mins  = v => { const n=parseFloat(v === null || v === undefined ? 0 : v); const h=Math.floor(n/60), m=Math.round(n%60); return h>0?`${h}h ${m}m`:`${m}m`; };
const na    = v => (v==null||v==='')?'<span style="color:#444">—</span>':v;
const fmtIso = (s) => { if (!s) return '—'; try { return new Date(s).toLocaleString(); } catch (_) { return esc(s); } };
const fmtDate = (s) => s ? esc(String(s).slice(0, 10)) : '—';
/** For `<input type="datetime-local">` from server ISO strings */
const isoToDatetimeLocal = (iso) => {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;
};
function orderDurationMin(startIso, endIso) {
  if (!startIso || !endIso) return '—';
  try {
    const a = new Date(startIso).getTime(), b = new Date(endIso).getTime();
    if (!(a > 0) || !(b > 0) || b < a) return '—';
    const mins = Math.round((b - a) / 60000);
    if (mins >= 1440) return Math.floor(mins / 1440) + 'd ' + Math.floor((mins % 1440) / 60) + 'h';
    if (mins >= 60) return Math.floor(mins / 60) + 'h ' + (mins % 60) + 'm';
    return mins + 'm';
  } catch (_) { return '—'; }
}


// --- public/js/reports/api.js ---
async function postJson(url, body) {
  const r = await fetch(API_BASE + url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ...body, token }),
  });
  if (!r.ok) {
    let msg = `Request failed (${r.status})`;
    try { const d = await r.json(); msg = d.error || msg; } catch (_) {}
    throw new Error(msg);
  }
  return r.json();
}


async function downloadResponseBlob(url, filename, opts = {}) {
  const r = await fetch(API_BASE + url, {
    method: opts.method || 'GET',
    headers: { ...(opts.headers || {}), 'x-session-token': token },
    body: opts.body,
  });
  if (!r.ok) {
    let msg = `Download failed (${r.status})`;
    try { const d = await r.json(); msg = d.error || msg; } catch (_) {}
    throw new Error(msg);
  }
  const blob = await r.blob();
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => {
    URL.revokeObjectURL(a.href);
    a.remove();
  }, 500);
}

async function downloadTrendCsv(days) {
  const meta = window.__lastReportMeta || {};
  const end = meta.reportEnd || meta.reportDate || '';
  const safeDays = Number(days || 365);
  try {
    await downloadResponseBlob(`/api/reports/trends.csv?days=${encodeURIComponent(safeDays)}${end ? `&end=${encodeURIComponent(end)}` : ''}`, `tgp_trends_${end || 'latest'}_${safeDays}d.csv`);
  } catch (e) { alert(e.message); }
}

async function downloadFullHistoryZip() {
  try {
    await downloadResponseBlob('/api/maintenance/export-history', 'tgp_full_history.zip', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ days: 365 }),
    });
  } catch (e) { alert(e.message); }
}


// --- public/js/reports/exports.js ---
function addStoreDays(dateStr, delta) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(dateStr || ''))) return '';
  const [y, m, d] = dateStr.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() + Number(delta || 0));
  return dt.toISOString().slice(0, 10);
}

function fileMaintenanceLogDate() {
  const meta = window.__lastReportMeta || {};
  const reportDate = meta.reportDate || meta.reportEnd || viewDate || '';
  if (reportDate && !meta.isLiveToday) return reportDate;
  return addStoreDays(reportDate || new Date().toISOString().slice(0, 10), -1) || reportDate;
}

async function openFileMaintenanceReceivingLog(format = 'print') {
  const day = fileMaintenanceLogDate();
  const fmt = format === 'csv' ? 'csv' : 'print';
  const url = `/api/export/receiving-file-maintenance?date=${encodeURIComponent(day)}&format=${fmt}`;
  if (fmt === 'csv') {
    try {
      await downloadResponseBlob(url, `Receiving_Log_${day}.csv`);
    } catch (e) { alert(e.message); }
    return;
  }
  const win = window.open('', '_blank');
  if (!win) { alert('Popup blocked. Allow popups for this app and try again.'); return; }
  win.document.write('<!doctype html><title>Receiving Log</title><body style="font-family:Arial,sans-serif;margin:24px">Loading receiving log…</body>');
  win.document.close();
  try {
    const r = await fetch(API_BASE + url, { headers: { 'x-session-token': token } });
    if (!r.ok) {
      let msg = `Download failed (${r.status})`;
      try { const d = await r.json(); msg = d.error || msg; } catch (_) {}
      throw new Error(msg);
    }
    const html = await r.text();
    win.document.open();
    win.document.write(html);
    win.document.close();
    try { win.focus(); } catch (_) {}
  } catch (e) {
    win.document.open();
    win.document.write(`<!doctype html><title>Receiving Log Error</title><body style="font-family:Arial,sans-serif;margin:24px;color:#900"><h1>Receiving Log Error</h1><p>${esc(e.message)}</p></body>`);
    win.document.close();
  }
}

async function printSafetyInspection(runId) {
  const id = String(runId || '').trim();
  if (!id) return;
  const url = `/api/export/safety-inspection?run_id=${encodeURIComponent(id)}`;
  const win = window.open('', '_blank');
  if (!win) { alert('Popup blocked. Allow popups for this app and try again.'); return; }
  win.document.write('<!doctype html><title>Safety Inspection</title><body style="font-family:Arial,sans-serif;margin:24px">Loading…</body>');
  win.document.close();
  try {
    const r = await fetch(API_BASE + url, { headers: { 'x-session-token': token } });
    if (!r.ok) {
      let msg = `Print failed (${r.status})`;
      try { const d = await r.json(); msg = d.error || msg; } catch (_) {}
      throw new Error(msg);
    }
    const html = await r.text();
    win.document.open();
    win.document.write(html);
    win.document.close();
    try { win.focus(); } catch (_) {}
  } catch (e) {
    win.document.open();
    win.document.write(`<!doctype html><title>Safety Inspection Error</title><body style="font-family:Arial,sans-serif;margin:24px;color:#900"><h1>Print Error</h1><p>${esc(e.message)}</p></body>`);
    win.document.close();
    alert(e.message);
  }
}

function reportRangeForExport() {
  const meta = window.__lastReportMeta || {};
  const start = meta.reportStart || meta.reportDate || viewStart || viewDate || new Date().toISOString().slice(0, 10);
  const end = meta.reportEnd || meta.reportDate || viewEnd || viewDate || start;
  return { start, end };
}

async function openExportPopup(url, loadingTitle, errorTitle) {
  const win = window.open('', '_blank');
  if (!win) { alert('Popup blocked. Allow popups for this app and try again.'); return null; }
  win.document.write(`<!doctype html><title>${esc(loadingTitle)}</title><body style="font-family:Arial,sans-serif;margin:24px">Loading…</body>`);
  win.document.close();
  try {
    const r = await fetch(API_BASE + url, { headers: { 'x-session-token': token } });
    if (!r.ok) {
      let msg = `Export failed (${r.status})`;
      try { const d = await r.json(); msg = d.error || msg; } catch (_) {}
      throw new Error(msg);
    }
    const html = await r.text();
    win.document.open();
    win.document.write(html);
    win.document.close();
    try { win.focus(); } catch (_) {}
    return win;
  } catch (e) {
    win.document.open();
    win.document.write(`<!doctype html><title>${esc(errorTitle)}</title><body style="font-family:Arial,sans-serif;margin:24px;color:#900"><h1>${esc(errorTitle)}</h1><p>${esc(e.message)}</p></body>`);
    win.document.close();
    alert(e.message);
    return null;
  }
}

async function printTgpColdChain(format = 'print') {
  const { start, end } = reportRangeForExport();
  const fmt = format === 'csv' ? 'csv' : 'print';
  const url = `/api/export/tgp-cold-chain?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}&format=${fmt}`;
  if (fmt === 'csv') {
    const fileLabel = start === end ? start : `${start}_${end}`;
    try {
      await downloadResponseBlob(url, `TGP_Cold_Chain_${fileLabel}.csv`);
    } catch (e) { alert(e.message); }
    return;
  }
  await openExportPopup(url, 'TGP Cold Chain', 'TGP Cold Chain Error');
}


// --- public/js/reports/print-picker.js ---
function visiblePrintSectionIds() {
  return PRINT_SECTIONS
    .map((s) => s.id)
    .filter((id) => document.getElementById(id));
}

function loadPrintSectionSelection() {
  try {
    const raw = sessionStorage.getItem('tgp_print_sections');
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : null;
  } catch (_) {
    return null;
  }
}

function savePrintSectionSelection(ids) {
  sessionStorage.setItem('tgp_print_sections', JSON.stringify(ids));
}

function resolvePrintSectionSelection(fallbackPreset) {
  const saved = loadPrintSectionSelection();
  if (saved && saved.length) return saved.filter((id) => document.getElementById(id));
  const preset = PRINT_PRESETS[fallbackPreset] || PRINT_PRESETS.handoff;
  return preset.filter((id) => document.getElementById(id));
}

function renderPrintSectionPicker(selectedIds) {
  const host = document.getElementById('print-section-groups');
  if (!host) return;
  const selected = new Set(selectedIds || []);
  const available = PRINT_SECTIONS.filter((s) => document.getElementById(s.id));
  const groups = [...new Set(available.map((s) => s.group))];
  host.innerHTML = groups.map((group) => {
    const items = available.filter((s) => s.group === group).map((s) => {
      const checked = selected.has(s.id) ? ' checked' : '';
      return `<label><input type="checkbox" class="print-section-cb" value="${escAttr(s.id)}"${checked}> ${esc(s.label)}</label>`;
    }).join('');
    return `<div class="print-section-group"><div class="print-section-group-title">${esc(group)}</div><div class="print-section-list">${items}</div></div>`;
  }).join('');
}

function readPrintSectionPickerSelection() {
  return [...document.querySelectorAll('#print-section-groups .print-section-cb:checked')].map((el) => el.value);
}

function applyPrintSectionVisibility(selectedIds) {
  const selected = new Set(selectedIds || []);
  PRINT_SECTIONS.forEach((s) => {
    const el = document.getElementById(s.id);
    if (!el) return;
    el.classList.toggle('print-section-hidden', !selected.has(s.id));
  });
}

function clearPrintSectionVisibility() {
  PRINT_SECTIONS.forEach((s) => {
    const el = document.getElementById(s.id);
    if (el) el.classList.remove('print-section-hidden');
  });
}

function openPrintSectionPicker() {
  const selected = resolvePrintSectionSelection('handoff');
  renderPrintSectionPicker(selected);
  document.getElementById('print-picker-backdrop')?.classList.add('open');
}

function closePrintSectionPicker() {
  document.getElementById('print-picker-backdrop')?.classList.remove('open');
}

function applyPrintPreset(name) {
  const preset = PRINT_PRESETS[name];
  const ids = name === 'none'
    ? []
    : (preset || PRINT_PRESETS.handoff).filter((id) => document.getElementById(id));
  renderPrintSectionPicker(ids);
}

function runPrintWithSections(selectedIds) {
  const ids = (selectedIds || []).filter((id) => document.getElementById(id));
  if (!ids.length) {
    alert('Select at least one report section to print.');
    return;
  }
  savePrintSectionSelection(ids);
  applyPrintSectionVisibility(ids);
  window.print();
  clearPrintSectionVisibility();
}

function confirmPrintSelected() {
  const ids = readPrintSectionPickerSelection();
  closePrintSectionPicker();
  runPrintWithSections(ids);
}

function printHandoffPreset() {
  runPrintWithSections(resolvePrintSectionSelection('handoff'));
}


// --- public/js/reports/corrections.js ---
function parseRosterText(raw) {
  return String(raw || '')
    .split(/[,;|]/)
    .map((n) => n.trim())
    .filter(Boolean);
}

function syncStaffCountFromRoster(row) {
  const rosterInput = row?.querySelector('.hist-staff-roster');
  const staffInput = row?.querySelector('.hist-staff-count');
  if (!rosterInput || !staffInput) return;
  const names = parseRosterText(rosterInput.value);
  if (names.length) staffInput.value = String(names.length);
}

async function saveReceivingLogCorrection(btn) {
  const row = btn.closest('tr');
  if (!row) return;
  const expId = row.dataset.expId;
  const arrivedAt = row.querySelector('.recv-arrived-at')?.value ?? '';
  const departedAt = row.querySelector('.recv-departed-at')?.value ?? '';
  const invoiceRef = row.querySelector('.recv-invoice-ref')?.value ?? '';
  btn.disabled = true;
  const oldText = btn.textContent;
  btn.textContent = 'SAVING';
  try {
    await postJson('/api/receiving-log-correction', {
      exp_id: expId,
      arrived_at: arrivedAt,
      departed_at: departedAt,
      invoice_ref: invoiceRef,
    });
    await loadReports();
  } catch (e) {
    alert(e.message);
  } finally {
    btn.disabled = false;
    btn.textContent = oldText;
  }
}

async function saveOrderHistoryCorrection(btn) {
  const row = btn.closest('tr');
  if (!row) return;
  syncStaffCountFromRoster(row);
  const storeDate = row.dataset.storeDate;
  const totalPieces = row.querySelector('.hist-total-pieces')?.value;
  const staffCount = row.querySelector('.hist-staff-count')?.value;
  const orderStart = row.querySelector('.hist-order-start')?.value;
  const orderEnd = row.querySelector('.hist-order-end')?.value;
  const exceptionReason = row.querySelector('.hist-exception-reason')?.value ?? '';
  const staffRoster = parseRosterText(row.querySelector('.hist-staff-roster')?.value ?? '');
  btn.disabled = true;
  const oldText = btn.textContent;
  btn.textContent = 'SAVING';
  try {
    await postJson('/api/order-history-correction', {
      store_date: storeDate,
      total_pieces: totalPieces,
      staff_count: staffCount,
      staff_roster: staffRoster,
      order_start: orderStart,
      order_end: orderEnd,
      exception_reason: exceptionReason,
    });
    await loadReports();
  } catch (e) {
    alert(e.message);
  } finally {
    btn.disabled = false;
    btn.textContent = oldText;
  }
}

async function attachLiveClockToHistory(btn) {
  const row = btn.closest('tr');
  if (!row) return;
  if (!confirm('Move the current live order clock onto this archived order row and clear the live clock?')) return;
  btn.disabled = true;
  const oldText = btn.textContent;
  btn.textContent = 'MOVING';
  try {
    await postJson('/api/order-history-attach-live-clock', { store_date: row.dataset.storeDate });
    await loadReports();
  } catch (e) {
    alert(e.message);
  } finally {
    btn.disabled = false;
    btn.textContent = oldText;
  }
}

async function deleteOrderHistoryRow(btn) {
  const row = btn.closest('tr');
  if (!row) return;
  const storeDate = row.dataset.storeDate;
  if (!confirm(`Delete order history for ${storeDate}? This cannot be undone.`)) return;
  btn.disabled = true;
  const oldText = btn.textContent;
  btn.textContent = 'DELETING';
  try {
    await postJson('/api/order-history-delete', { store_date: storeDate });
    await loadReports();
  } catch (e) {
    alert(e.message);
  } finally {
    btn.disabled = false;
    btn.textContent = oldText;
  }
}


// --- public/js/reports/auth.js ---
function connectReportsStream() {
  if (!token || typeof TgpStream === 'undefined') return;
  reportsStream?.close();
  reportsStream = TgpStream.connect({
    apiBase: API_BASE,
    token,
    onEvent(m) {
      if (m?.type !== 'REFRESH' && m?.type !== 'DELTA') return;
      countdown = 300;
      loadReports();
    },
  });
}

// ── AUTH ──────────────────────────────────────────────────────────────────────
async function initAuth() {
  if (token) { showMain(); return; }
  const statusEl = document.getElementById('auth-status');
  try {
    const r = await fetch(API_BASE + '/api/sync');
    if (!r.ok) {
      if (statusEl) statusEl.textContent = `Could not load staff list (HTTP ${r.status}). Retry or check the server.`;
      return;
    }
    const d = await r.json();
    const sel = document.getElementById('a-user');
    if (!sel) return;
    const staff = TgpApi.filterLoginStaff(d);
    if (!staff.length) {
      if (statusEl) statusEl.textContent = 'No login staff returned — check the staff directory.';
      return;
    }
    staff.forEach(s => {
      const o = document.createElement('option'); o.value = o.textContent = s.name; sel.appendChild(o);
    });
  } catch (e) {
    if (statusEl) statusEl.textContent = e.message || 'Network error loading login list.';
  }
}

async function doLogin() {
  const name = document.getElementById('a-user').value;
  const pin  = document.getElementById('a-pin').value;
  const statusEl = document.getElementById('auth-status');
  if (!name || !pin) { statusEl.textContent = 'Name and PIN required.'; return; }
  statusEl.textContent = '';
  try {
    const r = await fetch(API_BASE + '/api/mobile-auth', { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({name,pin}) });
    if (r.ok) {
      const d = await r.json();
      sessionStorage.setItem('tgp_token', d.token);
      token = d.token;
      showMain();
    } else {
      const d = await r.json();
      statusEl.textContent = d.error || 'Invalid credentials.';
    }
  } catch(e) { statusEl.textContent = 'Connection error.'; }
}

document.getElementById('a-pin')?.addEventListener('keydown', (e) => { if (e.key === 'Enter') doLogin(); });

function showMain() {
  document.getElementById('auth-screen').style.display = 'none';
  document.getElementById('main').style.display = 'block';
  wireReportActions();
  loadReports();
  startCountdown();
  loadBackups();
  connectReportsStream();
}

let reportActionsWired = false;
function wireReportActions() {
  if (reportActionsWired) return;
  const body = document.getElementById('report-body');
  if (!body) return;
  reportActionsWired = true;
  body.addEventListener('click', (e) => {
    const applyBtn = e.target.closest('[data-apply-est]');
    if (applyBtn) {
      applyRhythmEstimate(
        applyBtn.getAttribute('data-detail'),
        Number(applyBtn.getAttribute('data-est-mins')),
        applyBtn,
      );
      return;
    }
    const ackBtn = e.target.closest('[data-ack-action]');
    if (ackBtn) {
      ackReportAction(ackBtn.getAttribute('data-action-id'));
      return;
    }
    const deferBtn = e.target.closest('[data-defer-rhythm]');
    if (deferBtn) {
      let rhythmIds = [];
      try { rhythmIds = JSON.parse(deferBtn.getAttribute('data-rhythm-ids') || '[]'); } catch (_) { rhythmIds = []; }
      deferRhythmFromReport(deferBtn.getAttribute('data-store-date'), rhythmIds);
      return;
    }
    const modeBtn = e.target.closest('[data-report-mode]');
    if (modeBtn) {
      applyReportMode(modeBtn.getAttribute('data-report-mode'));
      return;
    }
    const addBtn = e.target.closest('[data-add-rhythm]');
    if (addBtn) {
      addRhythmFromReport(
        addBtn.getAttribute('data-detail'),
        Number(addBtn.getAttribute('data-est-mins')),
        Number(addBtn.getAttribute('data-samples')),
        addBtn,
      );
    }
  });
}

async function loadBackups() {
    const list = document.getElementById('backup-list');
    try {
        const r = await fetch(API_BASE + '/api/backups', { headers:{'x-session-token':token} });
        if (!r.ok) {
            let msg = `Backup list failed (HTTP ${r.status})`;
            if (r.status === 401 || r.status === 403) msg = 'Not authorized to load backups — re-login as manager.';
            if (list) list.innerHTML = `<div style="color:#f44;font-size:0.85em;padding:8px;">${msg}</div>`;
            return;
        }
        const d = await r.json();
        if (!list) return;
        list.innerHTML = `<button class="btn ${!activeBackup?'ok':''}" onclick="setBackup('')">CURRENT LIVE DB</button>`;
        (d.backups || []).forEach(f => {
            const btn = document.createElement('button');
            btn.className = `btn ${activeBackup===f?'ok':''}`;
            btn.textContent = f.replace('tgp_ops_backup_', '').replace('.db', '');
            btn.onclick = () => setBackup(f);
            list.appendChild(btn);
        });
        if (!(d.backups || []).length) {
            const note = document.createElement('div');
            note.style.cssText = 'color:#888;font-size:0.8em;padding:6px;';
            note.textContent = 'No backup files found yet.';
            list.appendChild(note);
        }
    } catch (e) {
        if (list) list.innerHTML = `<div style="color:#f44;font-size:0.85em;padding:8px;">${e.message || 'Network error loading backups.'}</div>`;
    }
}

function toggleHistory() {
    const el = document.getElementById('history-selector');
    el.style.display = el.style.display === 'none' ? 'block' : 'none';
}

function setBackup(name) {
  activeBackup = name;
  loadBackups();
  loadReports();
}

function applyViewDate() {
  const startEl = document.getElementById('report-view-start');
  const endEl = document.getElementById('report-view-end');
  viewStart = (startEl && startEl.value) ? startEl.value.trim() : '';
  viewEnd = (endEl && endEl.value) ? endEl.value.trim() : '';
  viewDate = '';
  const u = new URL(window.location.href);
  u.searchParams.delete('date');
  if (viewStart && /^\d{4}-\d{2}-\d{2}$/.test(viewStart)) u.searchParams.set('start', viewStart);
  else { u.searchParams.delete('start'); viewStart = ''; }
  if (viewEnd && /^\d{4}-\d{2}-\d{2}$/.test(viewEnd)) u.searchParams.set('end', viewEnd);
  else { u.searchParams.delete('end'); viewEnd = ''; }
  history.replaceState({}, '', u.pathname + (u.search || ''));
  loadReports();
}

async function ackReportAction(actionId) {
  if (!actionId) return;
  try {
    await postJson('/api/reports/ack-action', {
      action_id: actionId,
      report_date: (window.__lastReportMeta || {}).reportDate,
    });
    await loadReports();
  } catch (e) {
    alert(e.message);
  }
}

async function deferRhythmFromReport(storeDate, rhythmIds) {
  if (!rhythmIds?.length) return;
  if (!confirm('Defer these rhythm tasks for today and close matching open General routines on the board?')) return;
  try {
    await postJson('/api/reports/defer-rhythm', { store_date: storeDate, rhythm_ids: rhythmIds });
    await loadReports();
  } catch (e) {
    alert(e.message);
  }
}

async function applyRhythmEstimate(detail, estMins, btn) {
  if (!detail || !estMins) return;
  const oldText = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = 'APPLYING…'; }
  try {
    const result = await postJson('/api/reports/apply-rhythm-estimates', {
      updates: [{ detail, est_mins: estMins }],
    });
    if (!result.applied?.length) throw new Error('No rhythm template matched this task type.');
    await loadReports();
  } catch (e) {
    alert(e.message);
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = oldText; }
  }
}

async function addRhythmFromReport(detail, estMins, sampleCount, btn) {
  if (!detail || !estMins) return;
  const day = prompt('Rhythm day (Monday–Sunday or Everyday):', 'Everyday');
  if (day === null || !String(day).trim()) return;
  const zone = prompt('Zone:', 'General');
  if (zone === null || !String(zone).trim()) return;
  const priority = prompt('Priority (Routine / High / Urgent):', 'Routine');
  if (priority === null || !String(priority).trim()) return;
  const estRounded = Math.round(Number(estMins) / 5) * 5;
  const msg = `Add "${detail}" to rhythm on ${String(day).trim()}?\n\nEst: ${estRounded}m (from ${sampleCount || '?'} completed samples)\nZone: ${String(zone).trim()}\nPriority: ${String(priority).trim()}`;
  if (!confirm(msg)) return;
  const oldText = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = 'ADDING…'; }
  try {
    await postJson('/api/reports/add-to-rhythm', {
      detail,
      day: String(day).trim(),
      zone: String(zone).trim(),
      priority: String(priority).trim(),
      est_mins: estMins,
    });
    await loadReports();
  } catch (e) {
    alert(e.message);
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = oldText; }
  }
}


// --- public/js/reports/chrome.js ---
function applyReportMode(mode) {
  const allowed = ['today', 'learn', 'handoff'];
  if (!allowed.includes(mode)) mode = 'today';
  reportMode = mode;
  sessionStorage.setItem('tgp_report_mode', mode);
  document.querySelectorAll('.report-mode-tab').forEach((t) => {
    t.classList.toggle('active', t.dataset.mode === mode);
  });
  document.querySelectorAll('.report-mode-panel').forEach((p) => {
    p.classList.toggle('active', p.dataset.mode === mode);
  });
  const hints = {
    today: 'What do I need to act on right now? Daily Direction, Shift Updates, and Action Inbox.',
    learn: 'Weekly review — planning accuracy, scorecard health, trends, and what-if tools.',
    handoff: 'Close the shift — summary, comms archive, staff, receiving, and print handoff.',
  };
  const hintEl = document.getElementById('report-mode-hint');
  if (hintEl) hintEl.textContent = hints[mode] || hints.today;
}

function buildReportModeChrome(d) {
  const kpi = d.report_kpi_strip || {};
  const fah = d.finish_archive_health || {};
  const urgent = kpi.actions_urgent || 0;
  const todayBadge = urgent ? `<span class="mode-badge">${urgent} urgent</span>` : '';
  const learnBadge = (fah.phase0_ready === false)
    ? `<span class="mode-badge">archive</span>`
    : '';
  const hints = {
    today: 'What do I need to act on right now? Daily Direction, Shift Updates, and Action Inbox.',
    learn: 'Weekly review — planning accuracy, scorecard health, trends, and what-if tools.',
    handoff: 'Close the shift — summary, comms archive, staff, receiving, and print handoff.',
  };
  return `<nav class="report-modes" aria-label="Report modes">
    <button type="button" class="report-mode-tab${reportMode === 'today' ? ' active' : ''}" data-mode="today" onclick="applyReportMode('today')">TODAY — Command${todayBadge}</button>
    <button type="button" class="report-mode-tab${reportMode === 'learn' ? ' active' : ''}" data-mode="learn" onclick="applyReportMode('learn')">LEARN — Weekly${learnBadge}</button>
    <button type="button" class="report-mode-tab${reportMode === 'handoff' ? ' active' : ''}" data-mode="handoff" onclick="applyReportMode('handoff')">HANDOFF — EOD</button>
  </nav>
  <p class="report-mode-hint" id="report-mode-hint">${hints[reportMode] || hints.today}</p>`;
}

function buildExecStrip(d) {
  const m = d.meta || {};
  const rd = m.reportDate || d.today;
  const rs = m.reportStart || rd;
  const re = m.reportEnd || rd;
  const live = m.liveStoreDate || rd;
  const kpi = d.report_kpi_strip || {};
  const odb = d.order_day_briefing || {};
  const startVal = viewStart || rs;
  const endVal = viewEnd || re;
  const rangeChip = rs === re
    ? `<span class="chip">REPORT: ${esc(rs)}</span>`
    : `<span class="chip">RANGE: ${esc(rs)} → ${esc(re)}</span>`;
  const urgentChip = kpi.actions_urgent
    ? `<span class="chip warn">${kpi.actions_urgent} URGENT</span>`
    : `<span class="chip ok">CLEAR</span>`;
  const openChip = kpi.tasks_open != null
    ? `<span class="chip ${kpi.tasks_open > 5 ? 'warn' : ''}">${kpi.tasks_open} OPEN TASKS</span>`
    : '';
  const orderChip = (odb.is_order_day && kpi.order_adj_pph != null)
    ? `<span class="chip">ORDER ${Number(kpi.order_adj_pph).toFixed(1)} ADJ PPH</span>`
    : '';
  const fah = d.finish_archive_health || {};
  const fahChip = (fah.complete_order_days != null && !fah.phase0_ready)
    ? `<button type="button" class="chip warn" style="cursor:pointer;font-family:inherit;font-size:inherit" onclick="applyReportMode('learn')" title="Full detail in LEARN">ARCHIVE NEEDS WORK</button>`
    : (fah.phase0_ready ? `<span class="chip ok">SCORECARD OK</span>` : '');
  return `<div class="exec-strip" id="sec-exec">
    <span class="chip ${m.reportSource === 'backup' ? 'warn' : ''}">${m.reportSource === 'backup' ? 'BACKUP' : 'LIVE'}</span>
    ${rangeChip}
    ${m.reportSource !== 'backup' ? `<span class="chip">STORE: ${esc(live)}</span>` : ''}
    ${m.isLiveToday === false ? `<span class="chip warn">HISTORICAL</span>` : ''}
    ${urgentChip}
    ${openChip}
    ${orderChip}
    ${fahChip}
    <div style="margin-left:auto;display:flex;align-items:center;gap:8px;flex-wrap:wrap">
      <label for="report-view-start">START</label>
      <input type="date" id="report-view-start" value="${esc(startVal)}" />
      <label for="report-view-end">END</label>
      <input type="date" id="report-view-end" value="${esc(endVal)}" />
      <button type="button" class="btn ok" style="padding:6px 14px" onclick="applyViewDate()">APPLY RANGE</button>
    </div>
  </div>`;
}

function isOrderDayActive(d) {
  const odb = d.order_day_briefing || {};
  const ot = d.order_today || {};
  return !!odb.is_order_day || !!(ot.start && !ot.end);
}

function actionInboxCount(d) {
  const actions = d.report_actions || [];
  if (!actions.length) return 0;
  return actions.filter((a) => a.priority === 'urgent' || a.priority === 'warn').length || actions.length;
}


// --- public/js/reports/sections/today.js ---
function buildDailyDirectionSection(d) {
  const dd = d.daily_direction;
  if (!dd) return '';
  const meta = d.meta || {};
  const isHistorical = meta.isLiveToday === false || dd.archived === true || dd.source === 'posted_archive';
  const color = dd.status_color || 'var(--warn)';
  const posted = dd.posted || (dd.posted_at ? { posted_at: dd.posted_at, posted_by: dd.posted_by } : null);
  const inboxN = actionInboxCount(d);
  const riskNote = isHistorical
    ? `<p style="font-size:0.75rem;color:#888;text-transform:none;margin:0 0 12px">Saved manager-posted Daily Direction for ${esc(meta.reportDate || dd.store_date || d.today || '')}. Historical reports show the final visible direction plus the update history, not a regenerated draft.</p>`
    : (inboxN
      ? `<p style="font-size:0.75rem;color:var(--warn);text-transform:none;margin:0 0 12px"><a href="#" onclick="document.getElementById('sec-actions')?.scrollIntoView({behavior:'smooth'});return false">${inboxN} operational signal${inboxN === 1 ? '' : 's'} in Action Inbox below</a> — risks are not duplicated here.</p>`
      : `<p style="font-size:0.75rem;color:var(--ok);text-transform:none;margin:0 0 12px">No urgent operational signals — confirm on walk.</p>`);
  const wins = (dd.must_wins || []).filter((w) => w.text).map((w) => `<li>${esc(w.text)}</li>`).join('');
  const postedBlock = posted?.posted_at
    ? `<p style="font-size:0.75rem;color:var(--ok);text-transform:none;margin:8px 0">Daily Direction posted ${esc(String(posted.posted_at).slice(11, 16))} by ${esc(posted.posted_by || '')}</p>`
    : `<p style="font-size:0.75rem;color:#888;text-transform:none;margin:8px 0">Draft — amend and post from Management Hub → Daily Direction.</p>`;
  const updates = dd.shift_updates || [];
  const updatesBlock = updates.length
    ? `<div style="margin-top:12px"><div style="font-size:0.7rem;letter-spacing:2px;color:var(--warn);margin-bottom:6px">DAILY DIRECTION UPDATE HISTORY</div>
        ${updates.map((u) => `<div style="background:rgba(255,170,0,0.08);border-left:3px solid var(--warn);padding:8px;margin-bottom:8px;font-size:0.78rem;text-transform:none;white-space:pre-wrap">${esc(u.message)}<div style="font-size:0.68rem;opacity:0.65;margin-top:4px">${esc(String(u.posted_at || '').slice(11, 16))} · ${esc(u.posted_by || '')}</div></div>`).join('')}
      </div>`
    : '';
  const amend = dd.amendment_suggestion;
  const amendBlock = amend
    ? `<div style="background:rgba(255,170,0,0.1);border-left:3px solid var(--warn);padding:8px;margin-top:10px;font-size:0.78rem;text-transform:none"><strong>Amendment suggested:</strong> ${esc(amend.summary || '')}<div style="margin-top:4px;opacity:0.75">Act from the floor Management Hub → Daily Direction (ignore, dismiss, edit, or post Shift Update).</div></div>`
    : '';
  const intro = isHistorical
    ? 'Saved from the manager-posted Daily Direction. The visible direction reflects the latest update; the update history is retained below.'
    : 'System drafts from live data. Manager walks, amends, and posts — not auto-posted.';
  return `<div class="section" id="sec-daily-direction">
    <div class="section-title">DAILY DIRECTION${isHistorical ? ' — ARCHIVE' : ''}</div>
    <p style="font-size:0.72rem;color:#888;margin:-6px 0 12px;text-transform:none">${intro}</p>
    <div class="sum-card warn" style="border-left-color:${color};margin-bottom:12px">
      <div class="sum-label">STORE DAY STATUS</div>
      <div class="sum-val" style="color:${color};font-size:1.6rem">${esc(String(dd.status || 'yellow').toUpperCase())}</div>
      <div class="sum-sub" style="text-transform:none">${esc((dd.day_context || {}).weekday || '')}${(dd.day_context || {}).is_order_day ? ' · TGP Order Day' : ''}</div>
    </div>
    ${postedBlock}
    ${riskNote}
    <div style="margin-bottom:12px">
      <div style="font-size:0.7rem;letter-spacing:2px;color:var(--accent);margin-bottom:6px">MUST-WIN</div>
      <ul style="font-size:0.78rem;text-transform:none;line-height:1.45;padding-left:18px;margin:0">${wins || '<li style="opacity:0.7">Set after walk (Management Hub → Daily Direction)</li>'}</ul>
    </div>
    <div style="background:var(--panel);padding:12px;border-radius:8px;font-size:0.82rem;text-transform:none;line-height:1.45;white-space:pre-wrap">${esc(dd.floor_message || '')}</div>
    ${updatesBlock}
    ${amendBlock}
  </div>`;
}


function buildSafetyFocusSection(d) {
  const focus = d.daily_safety_focus || null;
  if (!focus || !focus.message) return '';
  const meta = d.meta || {};
  const label = focus.source === 'manual' ? 'MANAGER-SET' : 'DAILY ROTATION';
  const selected = focus.selected_at ? ` · selected ${fmtIso(focus.selected_at)}` : '';
  return `<div class="section" id="sec-safety-focus">
    <div class="section-title">DAILY SAFETY FOCUS — ${esc(meta.reportDate || focus.store_date || d.today || '')}</div>
    <div class="sum-card warn" style="border-left-color:var(--warn);margin-bottom:0">
      <div class="sum-label">${esc(label)}</div>
      <div class="sum-val" style="font-size:1.1rem;line-height:1.35;text-transform:none">${esc(focus.message)}</div>
      <div class="sum-sub" style="text-transform:none">${esc(focus.selected_by || 'AUTO')}${selected}</div>
    </div>
  </div>`;
}

function buildActionInbox(d) {
  const actions = d.report_actions || [];
  if (!actions.length) {
    const exportPull = `<div style="margin-bottom:10px"><a class="btn" href="${API_BASE}/api/export/kill-dates?format=print&amp;token=${encodeURIComponent(token || '')}" target="_blank" rel="noopener">PRINT PULL LIST</a>
    <a class="btn" style="margin-left:8px" href="${API_BASE}/api/export/kill-dates?format=csv&amp;token=${encodeURIComponent(token || '')}">CSV PULL + 7 DAY</a></div>`;
  return `<div class="section" id="sec-actions">
      <div class="section-title">ACTION INBOX — ${esc((d.meta || {}).reportDate || d.today)}</div>
      ${exportPull}
      <div class="action-card ok">
        <span class="action-pri" style="color:var(--ok)">CLEAR</span>
        <div class="action-body">
          <div class="action-title">NO URGENT MANAGER ACTIONS</div>
          <div class="action-detail">Floor exceptions and operational gaps look clear for this report view.</div>
        </div>
      </div>
    </div>`;
  }
  const cards = actions.map((a) => {
    const pri = a.priority === 'urgent' ? 'urgent' : (a.priority === 'warn' ? 'warn' : 'info');
    const priColor = pri === 'urgent' ? 'var(--urgent)' : (pri === 'warn' ? 'var(--warn)' : 'var(--accent)');
    const ackBtn = a.dismissible !== false && a.action_id
      ? `<div class="action-btns"><button type="button" class="btn" data-ack-action data-action-id="${escAttr(a.action_id)}">ACK / DISMISS</button></div>`
      : '';
    return `<div class="action-card ${pri}">
      <span class="action-pri" style="color:${priColor}">${esc(String(a.priority || 'info').toUpperCase())}</span>
      <div class="action-body">
        <div class="action-title">${esc(a.title)}</div>
        <div class="action-detail">${esc(a.detail)}</div>
        ${a.meta ? `<div class="action-meta">${esc(a.meta)}</div>` : ''}
        ${ackBtn}
      </div>
    </div>`;
  }).join('');
  const exportPull = `<div style="margin-bottom:10px"><a class="btn" href="${API_BASE}/api/export/kill-dates?format=print&amp;token=${encodeURIComponent(token || '')}" target="_blank" rel="noopener">PRINT PULL LIST</a>
    <a class="btn" style="margin-left:8px" href="${API_BASE}/api/export/kill-dates?format=csv&amp;token=${encodeURIComponent(token || '')}">CSV PULL + 7 DAY</a></div>`;
  return `<div class="section" id="sec-actions">
    <div class="section-title">ACTION INBOX — DO THIS NEXT</div>
    <p style="font-size:0.72rem;color:#888;margin:-6px 0 12px;text-transform:none">Same signals as the floor Management Hub — use this at huddle open or shift handoff.</p>
    ${exportPull}
    <div class="action-inbox">${cards}</div>
  </div>`;
}

function buildRhythmActionCell(r) {
  const suggestEst = r.avg_actual_mins;
  const biased = r.status === 'under_estimated' || r.status === 'over_estimated';
  if (r.has_rhythm_template && biased && suggestEst) {
    return `<button type="button" class="btn ok" style="padding:2px 8px;font-size:0.65rem" data-apply-est data-detail="${escAttr(r.task_type)}" data-est-mins="${Number(suggestEst)}">APPLY ${suggestEst}M</button>`;
  }
  if (r.can_add_to_rhythm && suggestEst) {
    return `<button type="button" class="btn warn" style="padding:2px 8px;font-size:0.65rem" data-add-rhythm data-detail="${escAttr(r.task_type)}" data-est-mins="${Number(suggestEst)}" data-samples="${Number(r.sample_count || 0)}">ADD TO RHYTHM</button>`;
  }
  if (r.has_rhythm_template) {
    return '<span style="color: #b0b0b0;font-size:0.65rem;text-transform:none">In rhythm</span>';
  }
  if (r.task_type === 'PULL:*') {
    return '<span style="color: #b0b0b0;font-size:0.65rem;text-transform:none">Grouped pulls</span>';
  }
  if (Number(r.sample_count || 0) < 3) {
    return '<span style="color: #b0b0b0;font-size:0.65rem;text-transform:none">Need 3+ samples</span>';
  }
  return '—';
}


function fmtDeltaPct(card) {
  const n = Number(card?.delta_pct || 0);
  if (!Number.isFinite(n) || n === 0) return '0%';
  return `${n > 0 ? '+' : ''}${n}%`;
}

function trendCardClass(card) {
  const key = card?.key || '';
  const n = Number(card?.delta_pct || 0);
  if (!n) return '';
  if (['oos_opened', 'outdated_item_logs', 'expiry_pull_logs', 'urgent_tasks_created'].includes(key)) return n > 0 ? 'warn' : 'ok';
  if (['avg_adjusted_pph', 'tasks_closed', 'oos_closed', 'daily_direction_posted_days'].includes(key)) return n < 0 ? 'warn' : 'ok';
  return '';
}


// --- public/js/reports/sections/learn.js ---
function buildTrendsSection(d) {
  const t = d.trends || {};
  const cards = t.cards || [];
  const insights = t.insights || [];
  const rows = t.daily_rows || [];
  const cardHtml = cards.slice(0, 10).map((c) => `<div class="sum-card ${trendCardClass(c)}">
      <div class="sum-label">${esc(c.label || c.key || '')}</div>
      <div class="sum-val" style="font-size:1.25rem">${na(c.current)}</div>
      <div class="sum-sub">${fmtDeltaPct(c)} VS PREV · ${na(c.previous)}</div>
    </div>`).join('');
  const insightHtml = insights.length
    ? insights.map((i) => {
        const cls = i.severity === 'warn' ? 'warn' : (i.severity === 'ok' ? 'ok' : '');
        return `<div class="action-card ${cls}">
          <span class="action-pri" style="color:${i.severity === 'warn' ? 'var(--warn)' : (i.severity === 'ok' ? 'var(--ok)' : 'var(--accent)')}">${esc(String(i.severity || 'info').toUpperCase())}</span>
          <div class="action-body">
            <div class="action-title">${esc(i.title || '')}</div>
            <div class="action-detail">${esc(i.detail || '')}</div>
          </div>
        </div>`;
      }).join('')
    : '<div style="font-size:0.75rem;color: #b0b0b0">NO INSIGHTS YET</div>';
  const rowHtml = rows.slice(-14).reverse().map((r) => `<tr>
      <td>${esc(r.store_date)}</td>
      <td>${r.tasks_created || 0}</td>
      <td>${r.tasks_closed || 0}</td>
      <td>${r.oos_opened || 0}/${r.oos_closed || 0}</td>
      <td>${r.outdated_item_logs || 0}</td>
      <td>${r.expiry_pull_logs || 0}</td>
      <td>${r.order_pieces || 0}</td>
      <td>${r.adjusted_pph == null ? '—' : Number(r.adjusted_pph).toFixed(1)}</td>
      <td>${r.daily_direction_posted ? 'YES' : 'NO'}</td>
      <td>${r.shift_updates_posted || 0}</td>
      <td style="font-size:0.68rem;color:var(--text);text-transform:none">${esc(r.manager_on_duty || '—')}</td>
    </tr>`).join('');
  return `<div class="section" id="sec-trends">
    <div class="section-title">LONG-TERM TRENDS &amp; INSIGHTS — ${esc(t.start_date || '')} → ${esc(t.end_date || '')}</div>
    <p style="font-size:0.72rem;color:#888;margin:-6px 0 12px;text-transform:none">Rule-based, explainable store trends from daily snapshots. Outdated Items uses the old internal shrink_log table but is reported as outdated/out-of-date work.</p>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">
      <button type="button" class="btn ok" onclick="downloadTrendCsv(365)">EXPORT TREND CSV</button>
      <button type="button" class="btn warn" onclick="downloadFullHistoryZip()">EXPORT FULL HISTORY ZIP (MANAGER)</button>
    </div>
    <div class="summary-grid" style="margin-bottom:14px">${cardHtml || '<div style="color: #b0b0b0;font-size:0.75rem">NO TREND CARDS YET</div>'}</div>
    <div class="two-col">
      <div>
        <div class="section-title" style="font-size:0.72rem;margin-bottom:8px">EXPLAINABLE INSIGHTS</div>
        <div class="action-inbox">${insightHtml}</div>
      </div>
      <div>
        <div class="section-title" style="font-size:0.72rem;margin-bottom:8px">RECENT DAILY SNAPSHOTS</div>
        <div class="tbl-wrap"><table>
          <tr><th>DATE</th><th>TASK IN</th><th>TASK DONE</th><th>OOS</th><th>OUTDATED</th><th>EXPIRY</th><th>PIECES</th><th>ADJ PPH</th><th>DD</th><th>UPD</th><th>LEAD</th></tr>
          ${rowHtml || '<tr><td colspan="11" style="color:#444;text-align:center;padding:16px">SNAPSHOTS WILL FILL IN AFTER EOD OR CSV EXPORT</td></tr>'}
        </table></div>
      </div>
    </div>
  </div>`;
}


function buildTaskPlanningSection(d, rangeLabel) {
  const tps = d.task_planning_summary || {};
  const overall = tps.overall;
  const rows = tps.by_type || [];
  if (!tps.sample_count || !overall) {
    return `<div class="section" id="sec-planning">
      <div class="section-title">TASK PLANNING ACCURACY — ${esc(rangeLabel)}</div>
      <p style="font-size:0.75rem;color: #b0b0b0;text-transform:none">Close tasks with est + actual times to build planning accuracy metrics.</p>
    </div>`;
  }
  const biasLabel = overall.bias_pct > 15 ? 'UNDER-ESTIMATED'
    : (overall.bias_pct < -15 ? 'OVER-ESTIMATED' : 'ON TRACK');
  const card = (label, val, sub) => `<div class="sum-card ok"><div class="sum-label">${label}</div><div class="sum-val" style="font-size:1.35rem">${val}</div>${sub ? `<div class="sum-sub">${sub}</div>` : ''}</div>`;
  return `<div class="section" id="sec-planning">
    <div class="section-title">TASK PLANNING ACCURACY — ${esc(rangeLabel)}</div>
    <div class="summary-grid" style="margin-bottom:12px">
      ${card('SAMPLES', tps.sample_count, 'HUMAN-CLOSED TASKS')}
      ${card('AVG EST', `${overall.avg_est_mins}M`, 'PLANNED')}
      ${card('AVG ACTUAL', `${overall.avg_actual_mins}M`, 'COMPLETED')}
      ${card('BIAS', `${overall.bias_mins >= 0 ? '+' : ''}${overall.bias_mins}M`, biasLabel)}
    </div>
    <div class="tbl-wrap"><table>
      <tr><th>TASK TYPE</th><th>SAMPLES</th><th>AVG EST</th><th>AVG ACTUAL</th><th>BIAS</th><th>STATUS</th><th>RHYTHM</th></tr>
      ${rows.map((r) => `<tr>
        <td style="color:var(--white);font-weight:700">${esc(r.task_type)}</td>
        <td>${r.sample_count}</td>
        <td>${r.avg_est_mins}m</td>
        <td>${r.avg_actual_mins}m</td>
        <td>${r.bias_mins >= 0 ? '+' : ''}${r.bias_mins}m (${r.bias_pct >= 0 ? '+' : ''}${r.bias_pct}%)</td>
        <td><span class="plan-status ${esc(r.status)}">${esc(String(r.status || '').replace(/_/g, ' ').toUpperCase())}</span></td>
        <td>${buildRhythmActionCell(r)}</td>
      </tr>`).join('')}
    </table></div>
    <p style="font-size:0.68rem;color: #b0b0b0;margin-top:10px;text-transform:none">Apply updates an existing rhythm template. Add to rhythm promotes recurring work (3+ samples) with the learned estimate.</p>
  </div>`;
}

function groupByField(rows, field) {
  const groups = {};
  (rows || []).forEach((r) => {
    const key = String(r[field] || 'UNKNOWN').slice(0, 10);
    if (!groups[key]) groups[key] = [];
    groups[key].push(r);
  });
  return Object.keys(groups).sort((a, b) => b.localeCompare(a)).map((k) => ({ key: k, rows: groups[k] }));
}

function renderGroupedStaffShifts(staffShifts, multiDay) {
  if (!staffShifts.length) {
    return '<tr><td colspan="7" style="color:#444;text-align:center;padding:16px">NO STAFF SCHEDULE IMPORTED FOR THIS RANGE</td></tr>';
  }
  if (!multiDay) {
    return staffShifts.map(r => `<tr>
      <td>${esc(r.shift_date || '')}</td>
      <td style="color:var(--white);font-weight:700">${esc(r.staff_name)}</td>
      <td>${esc(r.start_time || '')}</td>
      <td>${esc(r.end_time || '')}</td>
      <td>${esc(r.role || '')}</td>
      <td>${esc(r.department || '')}</td>
      <td style="font-size:0.75rem;color:var(--text)">${esc(r.notes || '')}</td>
    </tr>`).join('');
  }
  return groupByField(staffShifts, 'shift_date').map(g =>
    `<tr class="day-divider"><td colspan="7">— ${esc(g.key)} —</td></tr>` +
    g.rows.map(r => `<tr>
      <td>${esc(r.shift_date || '')}</td>
      <td style="color:var(--white);font-weight:700">${esc(r.staff_name)}</td>
      <td>${esc(r.start_time || '')}</td>
      <td>${esc(r.end_time || '')}</td>
      <td>${esc(r.role || '')}</td>
      <td>${esc(r.department || '')}</td>
      <td style="font-size:0.75rem;color:var(--text)">${esc(r.notes || '')}</td>
    </tr>`).join('')
  ).join('');
}

function renderGroupedCompletedTasks(completedTasks, multiDay) {
  if (!completedTasks.length) {
    return '<tr><td colspan="6" style="color:#444;text-align:center;padding:16px">NO TASKS COMPLETED FOR THIS RANGE</td></tr>';
  }
  const rowHtml = (t) => `<tr>
    <td style="font-size:0.72rem;color:var(--text)">${fmtIso(t.time_closed)}</td>
    <td style="color:var(--white)">${esc(t.task_detail)}</td>
    <td>${esc(t.zone)}</td>
    <td>${esc(t.closed_by || t.assigned_to || '')}</td>
    <td>${t.est_mins || 0}m</td>
    <td><span class="pill">${mins(t.actual_mins || 0)}</span></td>
  </tr>`;
  if (!multiDay) return completedTasks.map(rowHtml).join('');
  return groupByField(completedTasks, 'closed_date').map(g =>
    `<tr class="day-divider"><td colspan="6">— ${esc(g.key)} (${g.rows.length} TASKS) —</td></tr>` +
    g.rows.map(rowHtml).join('')
  ).join('');
}

// ---- Order-cadence simulator (what-if: more / fewer order days per week) ----
let __tgpCadenceOws = null;

function renderCadenceSimBody(ows, opts) {
  if (typeof TGPCadenceSim === 'undefined' || !ows) return '';
  let sim;
  try { sim = TGPCadenceSim.simulateOrderCadence(ows, opts || {}); }
  catch (_) { return ''; }
  if (!sim || !sim.ok) {
    const have = (sim && sim.baseline && sim.baseline.sample_days) || (ows.order_days || 0);
    return `<div style="font-size:0.75rem;color: #b0b0b0;padding:8px 0">NOT ENOUGH ARCHIVED ORDER DAYS YET TO SIMULATE (have ${have}). Finish a few order clocks and this fills in.</div>`;
  }
  const b = sim.baseline;
  const fmtDelta = (s) => {
    if (s.is_current) return '<span class="pill">CURRENT</span>';
    const up = s.delta_pph > 0;
    const flat = s.delta_pph === 0;
    const color = flat ? 'var(--text)' : (up ? 'var(--ok,#27e0a0)' : 'var(--urgent,#ff5a5a)');
    const sign = s.delta_pph_pct > 0 ? '+' : '';
    return `<span style="color:${color};font-weight:700">${sign}${s.delta_pph_pct}%</span>`;
  };
  const rows = sim.scenarios.map((s) => `<tr style="${s.is_current ? 'background:rgba(120,180,255,0.08)' : ''}">
      <td style="font-weight:700;color:var(--white)">${s.days_per_week}/wk</td>
      <td>${s.pieces_per_day}</td>
      <td>${mins(s.day_length_mins)}</td>
      <td>${s.break_per_person_hours.toFixed(2)}h</td>
      <td>${s.weekly_clock_person_hours}</td>
      <td><span class="pill">${s.effective_pph.toFixed(1)}</span></td>
      <td>${fmtDelta(s)}</td>
    </tr>`).join('');

  // Recommendation banner — best cadence in the swept range.
  const best = sim.best;
  let recBanner = '';
  if (best) {
    if (best.is_current) {
      recBanner = `<div style="border:1px solid var(--ok,#27e0a0);background:rgba(39,224,160,0.08);border-radius:8px;padding:10px 12px;margin-bottom:12px;font-size:0.8rem;color:var(--white)">
        ✓ <b>Your current cadence (${best.days_per_week}/wk) is already the most efficient</b> in this range — at the assumptions above, adding order days wouldn't lift effective PPH.</div>`;
    } else {
      const dir = best.delta_pph >= 0 ? '+' : '';
      const labor = best.delta_labor_hours;
      const laborTxt = labor === 0 ? 'same weekly labor'
        : `${labor < 0 ? labor : '+' + labor} labor person-hrs/wk`;
      recBanner = `<div style="border:1px solid var(--accent,#5aa0ff);background:rgba(90,160,255,0.08);border-radius:8px;padding:10px 12px;margin-bottom:12px;font-size:0.8rem;color:var(--white)">
        ▲ <b>Best in this sweep: ${best.days_per_week} order days/week</b> → effective ${best.effective_pph.toFixed(1)} PPH
        (<span style="color:${best.delta_pph >= 0 ? 'var(--ok,#27e0a0)' : 'var(--urgent,#ff5a5a)'}">${dir}${best.delta_pph_pct}%</span> vs current ${sim.current ? sim.current.days_per_week : ''}/wk, ${laborTxt}),
        with ~${best.pieces_per_day} pieces/day over ${mins(best.day_length_mins)}.</div>`;
    }
  }

  // Bar chart of effective PPH across cadences (axis zoomed to show differences).
  const pphs = sim.scenarios.map((s) => s.effective_pph);
  const minP = Math.min(...pphs);
  const maxP = Math.max(...pphs);
  const range = maxP - minP;
  const bars = sim.scenarios.map((s) => {
    const h = range > 0 ? Math.round(28 + (72 * (s.effective_pph - minP)) / range) : 60;
    const isBest = best && s.days_per_week === best.days_per_week;
    const barColor = s.is_current ? 'var(--accent,#5aa0ff)' : (isBest ? 'var(--ok,#27e0a0)' : '#46506a');
    return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;min-width:34px">
        <div style="font-size:0.6rem;color:#cdd;margin-bottom:2px">${s.effective_pph.toFixed(1)}</div>
        <div title="${s.days_per_week}/wk · ${s.effective_pph.toFixed(1)} PPH" style="width:62%;height:${h}%;background:${barColor};border-radius:4px 4px 0 0"></div>
        <div style="font-size:0.6rem;color:#9aa;margin-top:4px">${s.days_per_week}${s.is_current ? '*' : ''}</div>
      </div>`;
  }).join('');
  const chartHtml = `<div style="margin:4px 0 12px">
      <div style="display:flex;align-items:flex-end;gap:8px;height:120px;padding:6px 4px;border-bottom:1px solid #2a3142">${bars}</div>
      <div style="font-size:0.62rem;color: #b0b0b0;text-transform:none;margin-top:5px">EFFECTIVE PPH by order days/week — bar height is zoomed to the ${minP.toFixed(1)}–${maxP.toFixed(1)} range to show differences. <b>*</b> = current; green = best in range.</div>
    </div>`;

  return `
    ${recBanner}
    <div style="font-size:0.72rem;color:#9aa;text-transform:none;margin-bottom:10px">
      Holds your weekly volume (~<b>${b.weekly_pieces}</b> pieces, from ${b.avg_pieces}/day × ${b.days_per_week} order days),
      work rate (<b>${b.rate_pp_hour}</b> pieces / productive person-hour, break-adjusted) and staff/day constant,
      then splits the same work across different numbers of order days. The only modeled productivity change is your
      tiered break policy (longer days = more paid break per person). Sample: ${b.sample_days} order days / ${b.window_days}d.
    </div>
    ${chartHtml}
    <div style="display:flex;gap:14px;flex-wrap:wrap;align-items:flex-end;margin-bottom:10px">
      <label style="font-size:0.68rem;color:#9aa">STAFF / ORDER DAY
        <input id="cad-staff" type="number" min="1" max="30" step="1" value="${Math.round(opts && opts.staff ? opts.staff : b.avg_staff)}"
          style="display:block;width:90px;margin-top:3px;background:#0d1017;border:1px solid #2a3142;color:var(--white);padding:5px;border-radius:6px"></label>
      <label style="font-size:0.68rem;color:#9aa">SETUP HRS / ORDER DAY (overhead)
        <input id="cad-overhead" type="number" min="0" max="20" step="0.5" value="${opts && opts.overhead_hours_per_order_day ? opts.overhead_hours_per_order_day : 0}"
          style="display:block;width:90px;margin-top:3px;background:#0d1017;border:1px solid #2a3142;color:var(--white);padding:5px;border-radius:6px"></label>
      <label style="font-size:0.68rem;color:#9aa">MAX ORDER DAYS / WK
        <input id="cad-maxdays" type="number" min="1" max="7" step="1" value="${(opts && opts.max_days) || (b.days_per_week + 3)}"
          style="display:block;width:90px;margin-top:3px;background:#0d1017;border:1px solid #2a3142;color:var(--white);padding:5px;border-radius:6px"></label>
      <button type="button" class="btn" onclick="tgpCadenceRecalc()">RUN SIMULATION</button>
    </div>
    <div class="tbl-wrap"><table>
      <tr><th>ORDER DAYS</th><th>PIECES/DAY</th><th>ORDER LENGTH</th><th>BREAK/PERSON</th><th>WEEKLY LABOR (P-HRS)</th><th>EFFECTIVE PPH</th><th>Δ vs CURRENT</th></tr>
      ${rows}
    </table></div>
    <div style="font-size:0.68rem;color: #b0b0b0;text-transform:none;margin-top:8px">
      EFFECTIVE PPH = pieces ÷ total scheduled person-hours (incl. paid break + any setup overhead). “Δ vs current” &gt; 0 means more productive.
      Assumes a steady work rate and does not model travel, fatigue or vendor delivery limits — treat as a directional planning aid, not a guarantee.
    </div>`;
}

function tgpCadenceRecalc() {
  try {
    const out = document.getElementById('cadence-sim-out');
    if (!out || !__tgpCadenceOws) return;
    const num = (id) => { const el = document.getElementById(id); const n = parseFloat(el && el.value); return Number.isFinite(n) ? n : undefined; };
    out.innerHTML = renderCadenceSimBody(__tgpCadenceOws, {
      staff: num('cad-staff'),
      overhead_hours_per_order_day: num('cad-overhead'),
      max_days: num('cad-maxdays'),
    });
  } catch (_) { /* keep last good render */ }
}


// --- public/js/reports/sections/learn-metrics.js ---
function buildFinishHealthSection(d) {
  if (!d.finish_archive_health) return '';
  const f = d.finish_archive_health;
  const gaps = (f.missing_finish_days || []).slice(0, 5).map((g) => esc(g.store_date)).join(', ');
  return `<div class="section" id="sec-finish-health">
    <div class="section-title">FINISH ARCHIVE HEALTH</div>
    <div class="summary-grid" style="margin-bottom:10px">
      <div class="sum-card ${f.phase0_ready ? 'ok' : 'warn'}"><div class="sum-label">COMPLETE ORDER DAYS</div><div class="sum-val">${f.complete_order_days}</div><div class="sum-sub">${esc(f.scorecard_trust || 'building').toUpperCase()}</div></div>
      <div class="sum-card"><div class="sum-label">RECENT GAPS</div><div class="sum-val" style="font-size:1.1rem">${(f.missing_finish_days || []).length}</div><div class="sum-sub">${gaps || 'NONE IN WINDOW'}</div></div>
      <div class="sum-card"><div class="sum-label">INCOMPLETE ROWS</div><div class="sum-val" style="font-size:1.1rem">${(f.incomplete_rows || []).length}</div><div class="sum-sub">FIX IN ORDER HISTORY</div></div>
    </div>
    <p style="font-size:0.75rem;color:#888;text-transform:none">${esc(f.message || '')}</p>
  </div>`;
}

function laborVerdictClass(verdict) {
  if (verdict === 'surplus') return 'ok';
  if (verdict === 'tight') return 'warn';
  if (verdict === 'under') return 'urgent';
  return '';
}

function buildLaborLedgerSection(d) {
  const ll = d.labor_ledger;
  if (!ll) return '';
  const meta = d.meta || {};
  if (meta.isLiveToday === false && meta.reportStart !== meta.reportEnd) return '';
  const vCls = laborVerdictClass(ll.verdict);
  const card = (label, val, sub) => `<div class="sum-card ${vCls}"><div class="sum-label">${label}</div><div class="sum-val" style="font-size:1.35rem">${val}</div>${sub ? `<div class="sum-sub">${sub}</div>` : ''}</div>`;
  const sched = ll.scheduled || {};
  const committed = ll.committed || {};
  const drag = ll.fixed_drag || {};
  const svf = ll.schedule_vs_finish || {};
  const minBase = ll.minimum_baseline || {};
  const minBlock = minBase.minimum_hours != null
    ? `<div style="margin-top:10px;padding:10px;border-radius:8px;background:rgba(100,140,255,0.06);border-left:3px solid var(--accent);font-size:0.72rem;text-transform:none">
        <strong>Minimum hours baseline (Excel archive):</strong>
        ${Number(minBase.minimum_hours).toFixed(1)}h scheduled
        · actual ${sched.person_hours != null ? Number(sched.person_hours).toFixed(1) : '—'}h
        ${minBase.overage_pct != null ? ` · ${minBase.overage_pct > 0 ? '+' : ''}${minBase.overage_pct}% vs minimum` : ''}
        ${minBase.over_minimum ? ' · <span style="color:var(--warn)">OVER SOFT THRESHOLD</span>' : ''}
      </div>`
    : '';
  const buckets = (sched.by_bucket || []).map((b) =>
    `<span class="chip">${esc(b.label)}: ${Number(b.hours).toFixed(1)}h</span>`,
  ).join(' ');
  const reasons = (ll.reasons || []).map((r) => `<li>${esc(r)}</li>`).join('');
  const mismatchBlock = svf.mismatch || svf.complement_vs_expected != null
    ? `<div style="margin-top:10px;padding:10px;border-radius:8px;background:rgba(250,160,0,0.08);border-left:3px solid var(--warn);font-size:0.72rem;text-transform:none">
        <strong>Schedule vs FINISH:</strong>
        complement ${svf.schedule_complement || '—'}
        · FINISH staff ${svf.finish_staff_archived ?? svf.finish_staff_live ?? '—'}
        · typical ${svf.expected_staff ?? '—'}
        ${Array.isArray(svf.finish_roster) && svf.finish_roster.length ? ` · roster: ${svf.finish_roster.map((n) => esc(n)).join(', ')}` : ''}
      </div>`
    : '';
  return `<div class="section" id="sec-labor-ledger">
    <div class="section-title">LABOR LEDGER — ${esc(ll.store_date || '')}</div>
    <p style="font-size:0.72rem;color:#888;margin:-6px 0 12px;text-transform:none">Scheduled person-hours vs committed workload (rhythm + order + fixed drag). Use before huddle on order days.</p>
    <div class="summary-grid" style="margin-bottom:12px">
      ${card('VERDICT', esc(String(ll.verdict || 'unknown').toUpperCase()), esc(ll.verdict_detail || ''))}
      ${card('SCHEDULED HRS', sched.person_hours != null ? Number(sched.person_hours).toFixed(1) : '—', `${sched.complement || 0} people · ${sched.shift_rows || 0} rows`)}
      ${card('COMMITTED HRS', committed.person_hours != null ? Number(committed.person_hours).toFixed(1) : '—', `Rhythm ${Number(committed.rhythm_hours || 0).toFixed(1)} + Order ${Number(committed.order_hours || 0).toFixed(1)} + Drag ${Number(committed.fixed_drag_hours || 0).toFixed(1)}`)}
      ${card('SHIFT LEAD', esc(ll.shift_lead || d.shift_lead || '—'), ll.is_order_day ? 'ORDER DAY' : esc(ll.weekday || ''))}
    </div>
    ${buckets ? `<div style="margin-bottom:10px">${buckets}</div>` : ''}
    ${minBlock}
    ${reasons ? `<ul style="font-size:0.72rem;color:var(--text);text-transform:none;margin:0 0 10px 18px">${reasons}</ul>` : ''}
    ${mismatchBlock}
    <details style="margin-top:10px">
      <summary style="cursor:pointer;font-size:0.72rem;color:var(--accent);letter-spacing:1px">FIXED DRAG BREAKDOWN</summary>
      <div class="tbl-wrap" style="margin-top:8px"><table>
        <tr><th>ITEM</th><th>COUNT</th><th>EST MINS</th></tr>
        <tr><td>Vendor rhythm tasks</td><td>${drag.vendor_count || 0}</td><td>${drag.vendor_rhythm_mins || 0}</td></tr>
        <tr><td>Urgent/High open tasks</td><td>${drag.urgent_open_count || 0}</td><td>${drag.urgent_open_mins || 0}</td></tr>
        <tr><td>Expiry pulls due</td><td>${drag.pulls_due_count || 0}</td><td>${drag.pulls_due_mins || 0}</td></tr>
        <tr><td>Open customer orders</td><td>${drag.customer_orders_open || 0}</td><td>${drag.customer_orders_mins || 0}</td></tr>
        <tr><td>Pending receiving</td><td>${drag.vendors_pending || 0}</td><td>${drag.receiving_pending_mins || 0}</td></tr>
        <tr><td>Hardware not arrived</td><td>${drag.hardware_mins ? 1 : 0}</td><td>${drag.hardware_mins || 0}</td></tr>
      </table></div>
    </details>
  </div>`;
}

function buildExceptionRollupSection(d) {
  const rollup = d.exception_reason_rollup;
  if (!rollup || !(rollup.reasons || []).length) {
    return `<div class="section" id="sec-exception-rollup">
      <div class="section-title">ORDER DAY NOTES — 90 DAY ROLLUP</div>
      <p style="font-size:0.75rem;color: #b0b0b0;text-transform:none">Add day notes in order history when FINISH runs off-plan — patterns appear here.</p>
    </div>`;
  }
  const rows = rollup.reasons.map((r) => `<tr>
    <td style="color:var(--white);font-weight:700;text-transform:none">${esc(r.reason)}</td>
    <td><span class="pill">${r.count}</span></td>
    <td>${r.avg_staff ?? '—'}</td>
    <td>${r.avg_pieces ?? '—'}</td>
    <td style="font-size:0.68rem;color:var(--text);text-transform:none">${(r.recent_dates || []).map((dt) => esc(dt)).join(', ')}</td>
  </tr>`).join('');
  return `<div class="section" id="sec-exception-rollup">
    <div class="section-title">ORDER DAY NOTES — 90 DAY ROLLUP</div>
    <p style="font-size:0.72rem;color:#888;margin:-6px 0 12px;text-transform:none">${rollup.tagged_order_days} of ${rollup.total_order_days} archived order days tagged with a day note.</p>
    <div class="tbl-wrap"><table>
      <tr><th>REASON</th><th>TIMES</th><th>AVG STAFF</th><th>AVG PIECES</th><th>RECENT DATES</th></tr>
      ${rows}
    </table></div>
  </div>`;
}

function buildStaffCountCurveSection(d) {
  const curve = d.staff_count_curve || [];
  if (!curve.length) return '';
  const rows = curve.map((r) => `<tr>
    <td>${r.staff_count}</td>
    <td>${r.samples}</td>
    <td>${r.avg_adj_pph != null ? Number(r.avg_adj_pph).toFixed(1) : '—'}</td>
    <td>${r.avg_minutes != null ? mins(Math.round(r.avg_minutes)) : '—'}</td>
  </tr>`).join('');
  const wd = (d.order_day_briefing || {}).weekday || '';
  return `<div class="section" id="sec-staff-curve">
    <div class="section-title">STAFF COUNT vs ORDER PERFORMANCE${wd ? ` — ${esc(wd)}` : ''}</div>
    <p style="font-size:0.72rem;color:#888;margin:-6px 0 12px;text-transform:none">From FINISH archives — use when staffing order days.</p>
    <div class="tbl-wrap"><table>
      <tr><th>STAFF ON ORDER</th><th>SAMPLES</th><th>AVG ADJ PPH</th><th>AVG DURATION</th></tr>
      ${rows}
    </table></div>
  </div>`;
}

function buildActionLogsSection(d) {
  const acks = d.action_ack_log || [];
  const defers = d.rhythm_defer_log || [];
  if (!acks.length && !defers.length) {
    return `<div class="section" id="sec-action-logs">
      <div class="section-title">INBOX ACK &amp; RHYTHM DEFER LOG</div>
      <p style="font-size:0.75rem;color: #b0b0b0;text-transform:none">Dismissed inbox items and deferred rhythm tasks will appear here.</p>
    </div>`;
  }
  const ackRows = acks.slice(0, 25).map((a) => `<tr>
    <td style="font-size:0.72rem">${fmtIso(a.acked_at)}</td>
    <td>${esc(a.acked_by || '')}</td>
    <td>${esc(a.kind || '')}</td>
    <td style="font-size:0.68rem;color:var(--text);text-transform:none">${esc(a.action_id || '')}</td>
  </tr>`).join('');
  const deferRows = defers.slice(0, 25).map((e) => `<tr>
    <td>${esc(e.store_date || '')}</td>
    <td style="font-size:0.72rem">${e.deferred_at ? fmtIso(e.deferred_at) : '—'}</td>
    <td>${esc(e.deferred_by || (e.backfilled ? 'backfill' : ''))}</td>
    <td style="font-size:0.68rem;color:var(--text);text-transform:none">${(e.templates || []).map((t) => esc(t)).join('; ') || '—'}</td>
    <td>${e.closed_board_tasks || 0}</td>
  </tr>`).join('');
  return `<div class="section" id="sec-action-logs">
    <div class="section-title">INBOX ACK &amp; RHYTHM DEFER LOG</div>
    <div class="two-col">
      <div>
        <div class="section-title" style="font-size:0.72rem;margin-bottom:8px">INBOX DISMISSALS</div>
        <div class="tbl-wrap"><table>
          <tr><th>WHEN</th><th>BY</th><th>KIND</th><th>ACTION</th></tr>
          ${ackRows || '<tr><td colspan="4" style="color:#444;text-align:center;padding:12px">NONE YET</td></tr>'}
        </table></div>
      </div>
      <div>
        <div class="section-title" style="font-size:0.72rem;margin-bottom:8px">RHYTHM DEFERRALS</div>
        <div class="tbl-wrap"><table>
          <tr><th>DATE</th><th>WHEN</th><th>BY</th><th>TEMPLATES</th><th>CLOSED</th></tr>
          ${deferRows || '<tr><td colspan="5" style="color:#444;text-align:center;padding:12px">NONE YET</td></tr>'}
        </table></div>
      </div>
    </div>
  </div>`;
}


// --- public/js/reports/sections/roster-suggestions.js ---
function rosterSuggestionConfidenceLabel(confidence) {
  if (confidence === 'strong') return '3+ runs';
  if (confidence === 'solid') return '2 runs';
  return '1 run';
}

function renderRosterSuggestionCard(s, isTop) {
  return `<div class="roster-suggestion-card${isTop ? ' top' : ''}">
    <div class="rank">#${s.rank} · ${esc(rosterSuggestionConfidenceLabel(s.confidence))}</div>
    <div class="crew">${esc(s.roster_label || '')}</div>
    <div class="stats">${s.avg_adj_pph != null ? `${Number(s.avg_adj_pph).toFixed(1)} adj/person` : '—'}
      · ${s.avg_team_pph != null ? `${Number(s.avg_team_pph).toFixed(1)} team` : '—'}
      · ${s.avg_pieces ?? '—'} avg pcs
      · ${s.avg_minutes ? mins(Math.round(s.avg_minutes)) : '—'}</div>
  </div>`;
}

function buildRosterSuggestionsSection(d, { highlightWeekday = null, compact = false } = {}) {
  const data = d.roster_suggestions_by_weekday;
  if (!data) return '';
  const tagged = Number(data.roster_tagged_days || 0);
  const total = Number(data.total_order_days || 0);
  if (!tagged) {
    return `<div style="margin-top:${compact ? '12px' : '16px'}" id="sec-roster-suggestions">
      <div class="section-title" style="margin-bottom:6px">SUGGESTED ORDER CREWS</div>
      <p class="roster-suggestion-empty">Tag order crews in the history table above (comma-separated names + SAVE). Once a few order days have rosters, this section will rank the best crews for each Sunday, Tuesday, and Thursday order.</p>
    </div>`;
  }
  const dayBlocks = (data.by_weekday || []).map((day) => {
    const highlight = highlightWeekday && day.weekday === highlightWeekday;
    const cards = day.suggestions.length
      ? day.suggestions.map((s, i) => renderRosterSuggestionCard(s, i === 0)).join('')
      : `<p class="roster-suggestion-empty">${esc(day.weekday)}: ${day.roster_tagged_days || 0} tagged of ${day.sample_order_days || 0} archived orders — add more ${esc(day.weekday)} rosters to get a suggestion.</p>`;
    return `<div class="roster-suggestion-day${highlight ? ' highlight' : ''}">
      <div class="roster-suggestion-day-title">${esc(day.weekday)} ORDER${highlight ? ' · TODAY' : ''}</div>
      ${cards}
    </div>`;
  }).join('');
  const intro = compact
    ? `<p style="font-size:0.68rem;color:#888;margin:0 0 8px;text-transform:none">Best crews on past ${esc(highlightWeekday || 'this')} orders — ranked by avg adj/person PPH.</p>`
    : `<p style="font-size:0.72rem;color:#888;margin:-2px 0 10px;text-transform:none">Ranked by avg adj/person PPH on that weekday only. ${tagged} of ${total} archived order days have crew tags. #1 in each column is the suggested starting crew.</p>`;
  return `<div style="margin-top:${compact ? '12px' : '16px'}" id="sec-roster-suggestions">
    <div class="section-title" style="margin-bottom:6px">SUGGESTED ORDER CREWS — BY ORDER DAY</div>
    ${intro}
    <div class="roster-suggestions-grid">${dayBlocks}</div>
  </div>`;
}

function buildRosterPerformanceSection(d) {
  const rollup = d.roster_performance_rollup || [];
  if (!rollup.length) {
    return `<div style="margin-top:16px" id="sec-roster-performance">
      <div class="section-title" style="margin-bottom:6px">ORDER CREW PERFORMANCE</div>
      <p style="font-size:0.72rem;color: #b0b0b0;text-transform:none">Add comma-separated order crew names in the history table above — matching crews are grouped here by adjusted PPH.</p>
    </div>`;
  }
  const rows = rollup.map((r, i) => `<tr${i === 0 ? ' style="background:rgba(0,248,136,0.06)"' : ''}>
    <td style="color:var(--white);font-weight:700">${esc(r.roster_label || '')}</td>
    <td>${r.staff_count ?? '—'}</td>
    <td>${r.samples ?? '—'}</td>
    <td>${r.avg_pieces ?? '—'}</td>
    <td>${r.avg_minutes ? mins(Math.round(r.avg_minutes)) : '—'}</td>
    <td>${r.avg_team_pph != null ? Number(r.avg_team_pph).toFixed(1) : '—'}</td>
    <td>${r.avg_adj_pph != null ? Number(r.avg_adj_pph).toFixed(1) : '—'}</td>
    <td style="font-size:0.68rem;color:var(--text)">${(r.recent_dates || []).map((dt) => esc(dt)).join(', ')}</td>
  </tr>`).join('');
  return `<div style="margin-top:16px" id="sec-roster-performance">
    <div class="section-title" style="margin-bottom:6px">ORDER CREW PERFORMANCE — BY ROSTER</div>
    <p style="font-size:0.72rem;color:#888;margin:-2px 0 10px;text-transform:none">Grouped by crew (same names, any order). Top row is highest avg adj/person PPH. Edit rosters in the table above to backfill missing crews.</p>
    <div class="tbl-wrap"><table class="roster-rollup-table">
      <tr><th>ORDER CREW</th><th>SIZE</th><th>RUNS</th><th>AVG PCS</th><th>AVG DUR</th><th>AVG TEAM PPH</th><th>AVG ADJ/PER</th><th>RECENT DATES</th></tr>
      ${rows}
    </table></div>
  </div>`;
}


// --- public/js/reports/sections/order-history.js ---
function buildOrderTodayBlock(d) {
  const meta = d.meta || {};
  const rd = meta.reportDate || d.today;
  const ot = d.order_today || { start: '', end: '' };
  const odb = d.order_day_briefing || {};
  const om = d.order_metrics || {};
  const advisor = d.rhythm_load_advisor || {};
  if (!isOrderDayActive(d)) return '';
  const omArchiveMissing = om.archive_missing;
  const orderClockBanner = omArchiveMissing
    ? `<div style="margin-bottom:12px;padding:10px 12px;border:1px solid rgba(255,170,0,0.4);border-radius:8px;background:rgba(255,170,0,0.08);font-size:0.78rem;color:var(--warn);text-transform:none">No FINISH archive for this date yet — live clock shown; full history is in LEARN.</div>`
    : '';
  let briefing = '';
  if (odb.is_order_day) {
    const exp = odb.expected_pieces || {};
    const band = exp.avg != null ? `${exp.avg}${exp.min != null && exp.max != null ? ` (${exp.min}–${exp.max})` : ''}` : '—';
    const recent = (odb.recent_same_weekday || []).map((r) =>
      `<tr><td>${esc(r.store_date)}</td><td>${r.total_pieces}</td><td>${r.staff_count}</td><td>${r.actual_order_minutes ? mins(r.actual_order_minutes) : '—'}</td></tr>`,
    ).join('');
    const advisorBlock = (() => {
      if (!advisor.message) return '';
      const defer = (advisor.defer_candidates || []).map((t) => esc(t.detail)).join(', ');
      const deferIds = (advisor.defer_candidates || []).map((t) => t.id).filter(Boolean);
      const deferBtn = deferIds.length
        ? `<div style="margin-top:10px"><button type="button" class="btn warn" style="padding:6px 14px;font-size:0.72rem" data-defer-rhythm data-store-date="${escAttr(advisor.store_date || rd)}" data-rhythm-ids="${escAttr(JSON.stringify(deferIds))}">DEFER ${deferIds.length} ROUTINE TASK(S)</button></div>`
        : '';
      return `<div style="margin-top:14px;padding:12px;border:1px solid rgba(250,160,0,0.35);border-radius:8px;background:rgba(250,160,0,0.06)">
        <div style="font-size:0.72rem;color:var(--warn);letter-spacing:1px;margin-bottom:6px">RHYTHM LOAD ADVISOR — ${esc(advisor.piece_band?.label || 'ORDER DAY')}</div>
        <div style="font-size:0.78rem;color:var(--white);text-transform:none;line-height:1.4">${esc(advisor.message)}</div>
        ${defer ? `<div style="font-size:0.68rem;color:#888;margin-top:8px;text-transform:none">Defer candidates if heavy: ${defer}</div>` : ''}
        ${deferBtn}
      </div>`;
    })();
    briefing = `<div style="margin-top:4px">
      <div class="section-title" style="margin-bottom:10px">ORDER-DAY BRIEFING — ${esc(odb.weekday || 'TODAY')}</div>
      <div class="summary-grid" style="margin-bottom:12px">
        <div class="sum-card ok"><div class="sum-label">EXPECTED PIECES</div><div class="sum-val">${esc(band)}</div><div class="sum-sub">${odb.sample_count || 0} PRIOR ${esc(odb.weekday || '')} SAMPLES</div></div>
        <div class="sum-card warn"><div class="sum-label">TYPICAL DURATION</div><div class="sum-val">${odb.expected_duration_minutes ? mins(Math.round(odb.expected_duration_minutes)) : '—'}</div></div>
        <div class="sum-card purple"><div class="sum-label">TYPICAL STAFF</div><div class="sum-val">${odb.expected_staff ?? '—'}</div></div>
        <div class="sum-card ok"><div class="sum-label">TYPICAL ADJ PPH</div><div class="sum-val">${odb.expected_team_pph != null ? Number(odb.expected_team_pph).toFixed(1) : '—'}</div></div>
      </div>
      ${recent ? `<div class="tbl-wrap"><table><tr><th>DATE</th><th>PIECES</th><th>STAFF</th><th>DURATION</th></tr>${recent}</table></div>` : ''}
      ${buildRosterSuggestionsSection(d, { highlightWeekday: odb.weekday, compact: true })}
      ${advisorBlock}
    </div>`;
  }
  return `<div class="section" id="sec-orders-today">
    <div class="section-title">ORDER DAY — LIVE</div>
    ${orderClockBanner}
    <div class="summary-grid" style="margin-bottom:12px">
      <div class="sum-card ok"><div class="sum-label">ORDER START</div><div class="sum-val" style="font-size:1.1rem">${fmtIso(ot.start)}</div></div>
      <div class="sum-card warn"><div class="sum-label">ORDER END</div><div class="sum-val" style="font-size:1.1rem">${fmtIso(ot.end)}</div></div>
      <div class="sum-card purple"><div class="sum-label">ACTUAL ORDER TIME</div><div class="sum-val" style="font-size:1.5rem">${omArchiveMissing ? '—' : mins(om.actual_order_minutes || 0)}</div>
        <div class="sum-sub">${omArchiveMissing ? 'NO ARCHIVE' : `TEAM ${Number(om.team_pph || om.actual_pieces_per_hour || 0).toFixed(1)} PPH · ADJ ${Number(om.adjusted_per_person_pph || 0).toFixed(1)} · ${om.staff_count || 1} STAFF`}</div></div>
      <div class="sum-card ok"><div class="sum-label">PIECES</div><div class="sum-val" style="font-size:1.5rem">${omArchiveMissing ? '—' : (om.total_pieces || 0)}</div></div>
    </div>
    ${briefing}
    <p style="font-size:0.68rem;color: #b0b0b0;margin-top:10px;text-transform:none">90-day history, scorecard, and cadence simulator are in <button type="button" class="btn" style="padding:2px 10px;font-size:0.62rem;vertical-align:baseline" data-report-mode="learn">LEARN</button>.</p>
  </div>`;
}

function buildOrderLearnBlock(d) {
  const meta = d.meta || {};
  const rd = meta.reportDate || d.today;
  const ot = d.order_today || { start: '', end: '' };
  const osh = d.order_shift_history || [];
  const ows = d.order_weekly_scorecard || {};
  __tgpCadenceOws = ows;
  const om = d.order_metrics || {};
  const omArchiveMissing = om.archive_missing;
  const historyTable = `<div class="tbl-wrap"><table class="order-history-table">
    <tr><th>DATE</th><th>START</th><th>END</th><th>DUR</th><th>#</th><th>ORDER CREW</th><th>PCS</th><th>PPH</th><th>DAY NOTE</th><th>ACTIONS</th></tr>
    ${osh.length
      ? osh.map(r => {
          const teamPph = Number(r.team_pph || r.actual_pieces_per_hour || 0);
          const adjPerson = Number(r.adjusted_per_person_pph || 0);
          const staff = Number(r.staff_count || 1);
          const rosterValue = Array.isArray(r.staff_roster) && r.staff_roster.length
            ? r.staff_roster.join(', ')
            : '';
          const storeMins = Number(r.actual_order_minutes || 0);
          const rawMins = Number(r.raw_clock_minutes || 0);
          const spansDay = Number(r.spans_calendar_day || 0) === 1;
          const durationLabel = storeMins ? mins(storeMins) : orderDurationMin(r.order_start, r.order_end);
          const durationHint = (spansDay || (rawMins > storeMins && storeMins > 0))
            ? `<div class="order-history-detail">${spansDay ? 'Cross-day' : ''}${spansDay && rawMins > storeMins ? ' · ' : ''}${rawMins > storeMins ? `Clock ${mins(rawMins)}` : ''}</div>`
            : '';
          const pieceHint = `G ${Number(r.grocery_pieces || 0)} · F ${Number(r.frozen_pieces || 0)} · H ${Number(r.hardware_pieces || 0)}`;
          const staffWarn = staff <= 1 && adjPerson > teamPph
            ? ' title="Staff is 1 — break-adjusted rate can exceed team PPH. Add order crew names and SAVE." style="background:rgba(255,170,0,0.12)"'
            : '';
          return `<tr data-store-date="${esc(r.store_date)}"${staffWarn}>
          <td style="font-weight:700;color:var(--white);white-space:nowrap">${esc(r.store_date)}${spansDay ? ' <span class="pill" style="font-size:0.58rem;margin-left:4px">X-DAY</span>' : ''}</td>
          <td><input class="hist-input hist-input-time hist-order-start" type="datetime-local" value="${esc(isoToDatetimeLocal(r.order_start))}"/></td>
          <td><input class="hist-input hist-input-time hist-order-end" type="datetime-local" value="${esc(isoToDatetimeLocal(r.order_end))}"/></td>
          <td><span class="pill">${esc(durationLabel)}</span>${durationHint}</td>
          <td><input class="hist-input hist-input-staff hist-staff-count" type="number" min="1" max="99" value="${esc(r.staff_count || 1)}" title="Head count on order"/></td>
          <td><input class="hist-input hist-input-roster hist-staff-roster" type="text" value="${esc(rosterValue)}" placeholder="Name1, Name2, Name3" title="Comma-separated order crew — SAVE updates head count from names" onchange="syncStaffCountFromRoster(this.closest('tr'))"/></td>
          <td><input class="hist-input hist-input-pieces hist-total-pieces" type="number" min="0" max="99999" value="${esc(r.total_pieces || 0)}" title="${esc(pieceHint)}"/><div class="piece-hint">${pieceHint}</div></td>
          <td><div class="pph-stack"><strong>${teamPph.toFixed(1)}</strong><span>team · ${adjPerson.toFixed(1)} adj/person</span></div></td>
          <td><input class="hist-input hist-input-note hist-exception-reason" type="text" maxlength="200" value="${esc(r.exception_reason || '')}" placeholder="—"/></td>
          <td><div class="order-history-actions">
            <button type="button" class="btn ok" onclick="saveOrderHistoryCorrection(this)">SAVE</button>
            ${(r.store_date === rd && ot.start && ot.end) ? `<button type="button" class="btn warn" onclick="attachLiveClockToHistory(this)">MOVE CLOCK</button>` : ''}
            <button type="button" class="btn warn" onclick="deleteOrderHistoryRow(this)">DEL</button>
          </div><div class="order-history-detail">Archived ${fmtIso(r.recorded_at)}</div></td>
        </tr>`;
        }).join('')
      : '<tr><td colspan="10" style="color:#444;text-align:center;padding:16px">NO ARCHIVED ORDER TIMES YET</td></tr>'}
  </table></div>
  <p style="font-size:0.68rem;color: #b0b0b0;margin-top:8px;text-transform:none">Edit order crew names to compare teams in the roster rollup below. Piece breakdown (G/F/H) shows under PCS. PPH recalculates on SAVE.</p>`;
  const scorecard = (() => {
    const overall = ows.overall;
    const byDay = ows.by_weekday || [];
    if (!overall || !ows.order_days) {
      return `<div style="margin-top:14px;font-size:0.75rem;color: #b0b0b0">WEEKLY SCORECARD — NEED AT LEAST ONE ARCHIVED ORDER DAY</div>`;
    }
    const card = (label, val, sub) => `<div class="sum-card ok"><div class="sum-label">${label}</div><div class="sum-val" style="font-size:1.35rem">${val}</div>${sub ? `<div class="sum-sub">${sub}</div>` : ''}</div>`;
    return `<div style="margin-top:18px">
      <div class="section-title" style="margin-bottom:10px">WEEKLY ORDER SCORECARD — LAST ${ows.window_days || 90} DAYS</div>
      <div class="summary-grid" style="margin-bottom:12px">
        ${card('ORDER DAYS', ows.order_days, 'FINISH / CLOSED CLOCK ONLY')}
        ${card('AVG PIECES', overall.avg_pieces, 'PER ORDER DAY')}
        ${card('AVG DURATION', overall.avg_minutes ? mins(Math.round(overall.avg_minutes)) : '—', 'PER ORDER DAY')}
        ${card('AVG STAFF', overall.avg_staff, 'AT FINISH')}
        ${card('AVG TEAM PPH', Number(overall.avg_team_pph || 0).toFixed(1), 'TEAM RATE')}
        ${card('AVG ADJ/PERSON', Number(overall.avg_adj_pph || 0).toFixed(1), 'BREAK-ADJUSTED')}
      </div>
      <div class="tbl-wrap"><table>
        <tr><th>WEEKDAY</th><th>ORDER DAYS</th><th>AVG PIECES</th><th>AVG DURATION</th><th>AVG STAFF</th><th>AVG TEAM PPH</th><th>AVG ADJ/PERSON</th></tr>
        ${byDay.length ? byDay.map((row) => `<tr>
          <td style="font-weight:700;color:var(--white)">${esc(row.weekday)}</td>
          <td>${row.order_days}</td>
          <td>${row.avg_pieces ?? '—'}</td>
          <td>${row.avg_minutes ? mins(Math.round(row.avg_minutes)) : '—'}</td>
          <td>${row.avg_staff ?? '—'}</td>
          <td>${row.avg_team_pph != null ? Number(row.avg_team_pph).toFixed(1) : '—'}</td>
          <td>${row.avg_adj_pph != null ? Number(row.avg_adj_pph).toFixed(1) : '—'}</td>
        </tr>`).join('') : '<tr><td colspan="7" style="color:#444;text-align:center;padding:16px">NO WEEKDAY PATTERN YET</td></tr>'}
      </table></div>
    </div>`;
  })();
  const cadence = (() => {
    if (typeof TGPCadenceSim === 'undefined') return '';
    const body = renderCadenceSimBody(ows, {});
    if (!body) return '';
    return `<div style="margin-top:18px">
      <div class="section-title" style="margin-bottom:4px">ORDER CADENCE SIMULATOR</div>
      <div id="cadence-sim-out">${body}</div>
    </div>`;
  })();
  return `<div class="section" id="sec-orders-learn">
    <div class="section-title">ORDER HISTORY &amp; SCORECARD</div>
    ${omArchiveMissing ? `<p style="font-size:0.75rem;color:#888;text-transform:none;margin-bottom:10px">Archive gaps for this report date — correct rows below after FINISH runs.</p>` : ''}
    ${historyTable}
    ${buildRosterSuggestionsSection(d)}
    ${buildRosterPerformanceSection(d)}
    ${scorecard}
    ${cadence}
  </div>`;
}


// --- public/js/reports/sections/deliveries.js ---
function buildDeliveriesSection(d, rangeLabel, deliveries) {
  return `<div class="section" id="sec-deliveries">
    <div class="section-title">DELIVERY RECEIPTS — ${esc(rangeLabel)}
      <span style="float:right;display:flex;gap:8px;flex-wrap:wrap">
        <button type="button" class="btn" onclick="openFileMaintenanceReceivingLog('print')">PRINT REC LOG</button>
        <button type="button" class="btn" onclick="openFileMaintenanceReceivingLog('csv')">CSV</button>
      </span>
    </div>
    <p style="font-size:0.68rem;color: #b0b0b0;margin:0 0 10px;text-transform:none">Managers can correct time in/out and invoice/ref # when a late time out skews receiving stats or the invoice arrives after checkout. SAVE rebuilds dock duration.</p>
    <div class="tbl-wrap"><table class="order-history-table">
      <tr><th>VENDOR</th><th>STATUS</th><th>TIME IN</th><th>TIME OUT</th><th>INVOICE / REF #</th><th>DUR</th><th>BY</th><th>SAVE</th></tr>
      ${deliveries.length
        ? deliveries.map(r => {
          const editable = !!(r.arrived_at || r.departed_at);
          const durMins = (r.arrived_at && r.departed_at)
            ? orderDurationMin(r.arrived_at, r.departed_at)
            : '—';
          if (!editable) {
            return `<tr>
              <td style="color:var(--white);font-weight:700">${esc(r.vendor)}</td>
              <td><span class="pill">${esc(r.status)}</span></td>
              <td colspan="2" style="color: #b0b0b0;font-size:0.72rem;text-transform:none">No dock times logged</td>
              <td>${esc(r.invoice_ref || '')}</td>
              <td>—</td>
              <td>${esc(r.arrived_by || r.departed_by || r.closed_by || '')}</td>
              <td>—</td>
            </tr>`;
          }
          return `<tr data-exp-id="${esc(r.exp_id || '')}">
            <td style="color:var(--white);font-weight:700">${esc(r.vendor)}<div class="piece-hint">${esc(r.expected_day || '')}${r.pieces ? ` · ${r.pieces} pcs` : ''}${r.category ? ` · ${esc(r.category)}` : ''}</div></td>
            <td><span class="pill">${esc(r.status)}</span></td>
            <td><input class="hist-input hist-input-time recv-arrived-at" type="datetime-local" value="${esc(isoToDatetimeLocal(r.arrived_at))}"/></td>
            <td><input class="hist-input hist-input-time recv-departed-at" type="datetime-local" value="${esc(isoToDatetimeLocal(r.departed_at))}"/></td>
            <td><input class="hist-input hist-input-note recv-invoice-ref" type="text" maxlength="120" value="${esc(r.invoice_ref || '')}" placeholder="Invoice / ref #"/></td>
            <td><span class="pill recv-duration-preview">${esc(durMins)}</span></td>
            <td style="font-size:0.72rem;color:var(--text)">${esc(r.departed_by || r.arrived_by || r.closed_by || '')}</td>
            <td><button type="button" class="btn ok order-history-actions btn" style="padding:4px 10px;font-size:0.65rem" onclick="saveReceivingLogCorrection(this)">SAVE</button></td>
          </tr>`;
        }).join('')
        : '<tr><td colspan="8" style="color:#444;text-align:center;padding:16px">NO DELIVERIES RECORDED FOR THIS DATE</td></tr>'}
    </table></div>
  </div>`;
}


// --- public/js/reports/sections/panels.js ---
function buildTodayPanel(d) {
  let html = `<div class="report-mode-panel${reportMode === 'today' ? ' active' : ''}" data-mode="today">`;
  html += '<p class="mode-panel-intro">Today&apos;s operating command — act on direction and inbox items first.</p>';
  html += buildDailyDirectionSection(d);
  html += buildSafetyFocusSection(d);
  html += buildLaborLedgerSection(d);
  html += buildActionInbox(d);
  html += buildOrderTodayBlock(d);
  html += '</div>';
  return html;
}

function buildLearnPanel(d) {
  const meta = d.meta || {};
  const rd = meta.reportDate || d.today;
  const rs = meta.reportStart || rd;
  const re = meta.reportEnd || rd;
  const multiDay = rs !== re;
  const rangeLabel = multiDay ? `${rs} → ${re}` : rd;
  const markdownRecords = d.markdown_records || [];
  const oosCompare = d.oos_daily_comparison || {};
  const oos30 = d.oos_hotspots_30d || [];
  let html = `<div class="report-mode-panel${reportMode === 'learn' ? ' active' : ''}" data-mode="learn">`;
  html += '<p class="mode-panel-intro">Weekly improvement — planning, archive trust, trends, and strategic tools. Not for opening huddle.</p>';
  html += buildTaskPlanningSection(d, rangeLabel);
  html += buildFinishHealthSection(d);
  html += buildOrderLearnBlock(d);
  html += buildExceptionRollupSection(d);
  html += buildStaffCountCurveSection(d);
  html += buildActionLogsSection(d);
  html += buildTrendsSection(d);

  if (d.presence_summary?.enabled) {
    const ps = d.presence_summary;
    const snap = ps.latest_snapshot;
    const live = ps.live_board?.order_hint;
    const occ = (ps.zone_occupancy || ps.live_board?.analytics?.zone_occupancy || []).map((z) =>
      `<span class="chip">${esc(z.zone_key)}: ${z.count}</span>`,
    ).join(' ');
    const mode = esc((ps.asset_mode || 'staff').toUpperCase());
    html += `<div class="section" id="sec-presence">
      <div class="section-title">BLE PRESENCE — ${mode}</div>
      <p style="font-size:0.75rem;color:#888;text-transform:none;margin-bottom:8px">${esc(ps.disclaimer || '')}</p>
      <p style="font-size:0.72rem;color:#69c;text-transform:none;margin-bottom:10px">${esc(ps.architecture_note || '')}</p>
      <div class="summary-grid" style="margin-bottom:10px">
        <div class="sum-card ${snap ? 'ok' : 'warn'}"><div class="sum-label">FINISH SNAPSHOT</div><div class="sum-val" style="font-size:1.1rem">${snap ? (snap.inferred_staff ?? '—') : '—'}</div><div class="sum-sub">${snap?.asset_mode ? esc(snap.asset_mode).toUpperCase() : 'AT RECEIVING'}</div></div>
        <div class="sum-card"><div class="sum-label">LIVE (NOW)</div><div class="sum-val" style="font-size:1.1rem">${live ? live.beacon_count : '—'}</div><div class="sum-sub">${live?.count_label ? esc(live.count_label) : 'ORDER ZONE'}</div></div>
        <div class="sum-card ${(ps.live_board?.alerts?.offline_count || 0) ? 'warn' : 'ok'}"><div class="sum-label">OFFLINE GW</div><div class="sum-val" style="font-size:1.1rem">${ps.live_board?.alerts?.offline_count ?? 0}</div><div class="sum-sub">HUB + AISLE + CORNER</div></div>
      </div>
      ${occ ? `<div style="margin-bottom:10px">${occ}</div>` : ''}
    </div>`;
  }

  html += `<div class="section" id="sec-oos">
    <div class="section-title">OOS TRENDS &amp; RECURRING HOTSPOTS</div>
    <div class="two-col">
      <div>
        <div class="section-title" style="font-size:0.72rem;margin-bottom:8px">DAY COMPARISON — ${esc(rd)}</div>
        <div class="summary-grid">
          <div class="sum-card ${Number(oosCompare.today_holes || 0)>Number(oosCompare.previous_holes || 0)?'warn':'ok'}">
            <div class="sum-label">TODAY HOLES</div>
            <div class="sum-val">${oosCompare.today_holes || 0}</div>
            <div class="sum-sub">${oosCompare.today_incidents || 0} INCIDENTS</div>
          </div>
          <div class="sum-card">
            <div class="sum-label">PREVIOUS (${fmtDate(oosCompare.previous_date)})</div>
            <div class="sum-val">${oosCompare.previous_holes || 0}</div>
            <div class="sum-sub">${oosCompare.previous_incidents || 0} INCIDENTS</div>
          </div>
          <div class="sum-card purple">
            <div class="sum-label">DIFFERENCE</div>
            <div class="sum-val">${Number(oosCompare.today_holes || 0) - Number(oosCompare.previous_holes || 0)}</div>
            <div class="sum-sub">HOLES VS PREVIOUS DAY</div>
          </div>
        </div>
      </div>
      <div>
        <div class="section-title" style="font-size:0.72rem;margin-bottom:8px">30-DAY ZONE HOTSPOTS</div>
        <div class="tbl-wrap"><table>
          <tr><th>ZONE</th><th>TOTAL HOLES</th><th>INCIDENTS</th></tr>
          ${oos30.length
            ? oos30.map(r=>`<tr>
                <td>${esc(r.zone)}</td>
                <td><span class="pill" style="background:rgba(255,51,51,0.12);color:var(--urgent);border-color:rgba(255,51,51,0.3)">${r.total_holes}</span></td>
                <td>${r.incidents}</td>
              </tr>`).join('')
            : '<tr><td colspan="3" style="color:#444;text-align:center;padding:20px">NO OOS IN LAST 30 DAYS</td></tr>'}
        </table></div>
      </div>
    </div>
  </div>`;

  html += `<div class="section" id="sec-markdown">
    <div class="section-title">MARKDOWN / OUT-DATE RECORDS</div>
    <div class="tbl-wrap"><table>
      <tr><th>ITEM</th><th>CODE</th><th>ZONE</th><th>OUT DATE</th><th>STATUS</th><th>DAYS</th><th>CLOSED BY</th></tr>
      ${markdownRecords.length
        ? markdownRecords.map(k=>`<tr>
            <td style="color:var(--white);font-weight:700">${esc(k.item)}</td>
            <td>${esc(k.item_code || '')}</td>
            <td>${esc(k.zone || '')}</td>
            <td>${fmtDate(k.kill_date)}</td>
            <td><span class="pill">${esc(k.status)}</span></td>
            <td>${k.days_until == null ? '' : esc(k.days_until)}</td>
            <td>${esc(k.closed_by || '')}</td>
          </tr>`).join('')
        : '<tr><td colspan="7" style="color:#444;text-align:center;padding:16px">NO MARKDOWN RECORDS IN THIS WINDOW</td></tr>'}
    </table></div>
  </div>`;

  if (d.audit_scores.length) {
    html += `<div class="section" id="sec-homebase">
      <div class="section-title">HOMEBASE AUDIT SCORES — ${esc(rd)}</div>
      <div class="tbl-wrap"><table>
        <tr><th>ZONE</th><th>AUDITS</th><th>FRONT EDGE</th><th>TAG INTEGRITY</th><th>HOLE STRATEGY</th><th>CLEARANCES</th><th>OVERALL</th></tr>
        ${d.audit_scores.map(r => {
          const avg = Math.round(((parseInt(r.front_edge||0)+parseInt(r.tag_integrity||0)+parseInt(r.hole_strategy||0)+parseInt(r.clearances||0))/4));
          return `<tr>
            <td style="color:var(--white);font-weight:700">${esc(r.zone_name)}</td>
            <td>${r.total_audits}</td>
            <td>${score(r.front_edge)}</td>
            <td>${score(r.tag_integrity)}</td>
            <td>${score(r.hole_strategy)}</td>
            <td>${score(r.clearances)}</td>
            <td>${score(avg)}</td>
          </tr>`;
        }).join('')}
      </table></div>
    </div>`;
  }

  html += '</div>';
  return html;
}


// --- public/js/reports/sections/handoff.js ---
function buildHandoffPanel(d) {
  const meta = d.meta || {};
  const rd = meta.reportDate || d.today;
  const rs = meta.reportStart || rd;
  const re = meta.reportEnd || rd;
  const multiDay = rs !== re;
  const rangeLabel = multiDay ? `${rs} → ${re}` : rd;
  const s = d.shift;
  const tZone = d.task_closed_by_zone || [];
  const tPri = d.task_closed_by_priority || [];
  const tOpenZ = d.tasks_open_by_zone || [];
  const completedTasks = d.completed_tasks || [];
  const customerOrders = d.customer_orders || [];
  const deliveries = d.deliveries || [];
  const staffShifts = d.staff_shifts || [];
  let html = `<div class="report-mode-panel${reportMode === 'handoff' ? ' active' : ''}" data-mode="handoff">`;
  html += '<p class="mode-panel-intro">End-of-shift continuity — summary, comms archive, staff, receiving. Use Print Handoff for documentation.</p>';

  html += `<div class="section" id="sec-summary">
    <div class="section-title">SHIFT SUMMARY — ${esc(rangeLabel)}</div>
    <div class="summary-grid">
      <div class="sum-card ok"><div class="sum-label">TASKS COMPLETED</div><div class="sum-val">${s.tasks_completed}</div><div class="sum-sub">${s.tasks_open} STILL OPEN</div></div>
      <div class="sum-card ${s.oos_logged>0?'warn':'ok'}"><div class="sum-label">OOS LOGGED</div><div class="sum-val">${s.oos_logged}</div><div class="sum-sub">${s.oos_cleared} CLEARED</div></div>
      <div class="sum-card purple"><div class="sum-label">SPECIAL ORDERS</div><div class="sum-val">${s.orders_filled}</div><div class="sum-sub">${s.orders_open} STILL OPEN</div></div>
      <div class="sum-card ok"><div class="sum-label">VENDORS IN</div><div class="sum-val">${s.vendors_received}</div><div class="sum-sub">${s.vendors_pending} PENDING</div></div>
      <div class="sum-card ${s.kill_dates_due>0?'urgent':'ok'}"><div class="sum-label">PULLS DUE</div><div class="sum-val">${s.kill_dates_due}</div><div class="sum-sub">ACTIVE KILL DATES</div></div>
      <div class="sum-card ok"><div class="sum-label">SHIFT LEAD</div><div class="sum-val" style="font-size:1rem;text-transform:none">${esc(d.shift_lead || '—')}</div><div class="sum-sub">ACTIVE PREMIUM / SHIFT LEAD</div></div>
    </div>
  </div>`;

  html += buildSafetyFocusSection(d);

  const finishRoster = d.order_finish_roster || [];
  if (finishRoster.length) {
    html += `<div class="section" id="sec-order-roster">
      <div class="section-title">ORDER CREW (FINISH) — ${esc(rd)}</div>
      <p style="font-size:0.78rem;color:var(--white);text-transform:none;margin:0">${finishRoster.map((n) => esc(n)).join(' · ')}</p>
    </div>`;
  }

  const handoff = d.comms_handoff;
  if (handoff && Array.isArray(handoff.messages) && handoff.messages.length) {
    const rows = handoff.messages.map((m) => `<tr>
      <td>${esc(m.lane || '')}</td>
      <td>${esc(m.priority || '')}</td>
      <td>${esc(m.source || '')}</td>
      <td>${esc(m.posted_by || '')}</td>
      <td style="font-size:0.72rem">${fmtIso(m.posted_at)}</td>
      <td>${esc(m.body || '')}</td>
    </tr>`).join('');
    html += `<div class="section" id="sec-comms">
      <div class="section-title">COMMS HANDOFF — EOD ARCHIVE (${esc(handoff.store_date || rd)})</div>
      <p style="font-size:0.78rem;color:#888;margin:0 0 12px;text-transform:none">Messages archived at ${fmtIso(handoff.archived_at)} when the store day rolled.</p>
      <div class="tbl-wrap"><table>
        <tr><th>LANE</th><th>PRIORITY</th><th>SOURCE</th><th>BY</th><th>POSTED</th><th>BODY</th></tr>
        ${rows}
      </table></div>
    </div>`;
  }

  html += `<div class="section" id="sec-staff">
    <div class="section-title">STAFF ON SHIFT — ${esc(rangeLabel)}</div>
    <div class="tbl-wrap"><table>
      <tr><th>DATE</th><th>NAME</th><th>START</th><th>END</th><th>ROLE</th><th>DEPT</th><th>NOTES</th></tr>
      ${renderGroupedStaffShifts(staffShifts, multiDay)}
    </table></div>
  </div>`;

  html += `<div class="section" id="sec-tasks"><div class="section-title">TASKS — ${esc(rangeLabel)}</div>`;
  html += `<div class="section" style="margin-bottom:0">
    <div class="section-title">TASK LEADERBOARD</div>
    <div class="tbl-wrap"><table>
      <tr><th>#</th><th>TEAM MEMBER</th><th>TASKS COMPLETED</th></tr>
      ${d.task_leaderboard.length
        ? d.task_leaderboard.map((r,i)=>{
            const top = i < 3 && r.count > 0;
            const rowCls = top ? 'leader-top' : (r.count === 0 ? 'leader-zero' : '');
            return `<tr class="${rowCls}">
            <td class="rank">${top ? (i===0?'🥇':i===1?'🥈':'🥉') : i+1}</td>
            <td>${esc(r.name)}</td>
            <td><span class="pill">${r.count}</span></td>
          </tr>`;
          }).join('')
        : '<tr><td colspan="3" style="color:#444;text-align:center;padding:20px">NO DATA YET</td></tr>'}
    </table></div>
  </div>`;
  html += `<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin-top:16px">
    <div class="tbl-wrap"><table><caption style="caption-side:top;text-align:left;padding:0 0 8px 4px;font-size:0.7rem;color:var(--accent);letter-spacing:1px">CLOSED BY ZONE</caption>
      <tr><th>ZONE</th><th>COUNT</th></tr>
      ${tZone.length ? tZone.map(r=>`<tr><td>${esc(r.zone)}</td><td><span class="pill">${r.cnt}</span></td></tr>`).join('') : '<tr><td colspan="2" style="color:#444">NONE</td></tr>'}
    </table></div>
    <div class="tbl-wrap"><table><caption style="caption-side:top;text-align:left;padding:0 0 8px 4px;font-size:0.7rem;color:var(--accent);letter-spacing:1px">CLOSED BY PRIORITY</caption>
      <tr><th>PRIORITY</th><th>COUNT</th></tr>
      ${tPri.length ? tPri.map(r=>`<tr><td>${esc(r.priority)}</td><td><span class="pill">${r.cnt}</span></td></tr>`).join('') : '<tr><td colspan="2" style="color:#444">NONE</td></tr>'}
    </table></div>
    <div class="tbl-wrap"><table><caption style="caption-side:top;text-align:left;padding:0 0 8px 4px;font-size:0.7rem;color:var(--accent);letter-spacing:1px">OPEN BY ZONE</caption>
      <tr><th>ZONE</th><th>OPEN</th></tr>
      ${tOpenZ.length ? tOpenZ.map(r=>`<tr><td>${esc(r.zone)}</td><td><span class="pill">${r.cnt}</span></td></tr>`).join('') : '<tr><td colspan="2" style="color:#444">NONE</td></tr>'}
    </table></div>
  </div></div>`;

  html += `<details class="handoff-details section">
    <summary>COMPLETED TASK DETAIL (${completedTasks.length} TASKS)</summary>
    <div class="tbl-wrap"><table>
      <tr><th>CLOSED</th><th>TASK</th><th>ZONE</th><th>BY</th><th>EST</th><th>ACTUAL</th></tr>
      ${renderGroupedCompletedTasks(completedTasks, multiDay)}
    </table></div>
  </details>`;

  html += `<div class="section" id="sec-customer-orders">
    <div class="section-title">CUSTOMER ORDERS — ${esc(rangeLabel)}</div>
    <div class="tbl-wrap"><table>
      <tr><th>STATUS</th><th>CUSTOMER</th><th>ITEM</th><th>LOCATION</th><th>CONTACT</th><th>LOGGED</th><th>CLOSED</th><th>AGE</th></tr>
      ${customerOrders.length
        ? customerOrders.map(o=>`<tr>
            <td><span class="pill">${esc(o.status)}</span></td>
            <td style="color:var(--white);font-weight:700">${esc(o.customer)}</td>
            <td>${esc(o.item)}</td>
            <td>${esc(o.location)}</td>
            <td>${esc(o.contact)}</td>
            <td style="font-size:0.72rem;color:var(--text)">${fmtIso(o.time_logged)}</td>
            <td style="font-size:0.72rem;color:var(--text)">${fmtIso(o.time_closed)}</td>
            <td>${mins(o.age_mins || 0)}</td>
          </tr>`).join('')
        : '<tr><td colspan="8" style="color:#444;text-align:center;padding:16px">NO CUSTOMER ORDERS FOUND</td></tr>'}
    </table></div>
  </div>`;

  html += `<div class="section" id="sec-receiving">
    <div class="section-title">RECEIVING PERFORMANCE — BY VENDOR</div>
    <div class="tbl-wrap"><table>
      <tr><th>VENDOR</th><th>RUNS</th><th>AVG TIME</th><th>BEST</th><th>WORST</th><th>LAST ARRIVAL</th></tr>
      ${d.receiving_by_vendor.length
        ? d.receiving_by_vendor.map(r=>`<tr>
            <td style="color:var(--white);font-weight:700">${esc(r.vendor)}</td>
            <td>${r.runs}</td>
            <td>${mins(r.avg_mins)}</td>
            <td style="color:var(--ok)">${mins(r.best_mins)}</td>
            <td style="color:var(--warn)">${mins(r.worst_mins)}</td>
            <td style="font-size:0.75rem;color:var(--text)">${r.last_arrival ? new Date(r.last_arrival).toLocaleDateString() : '—'}</td>
          </tr>`).join('')
        : '<tr><td colspan="6" style="color:#444;text-align:center;padding:20px">NO RECEIVING DATA YET</td></tr>'}
    </table></div>
  <div class="two-col">`;
  html += `<div class="section">
    <div class="section-title">RECEIVING — BY TEAM MEMBER</div>
    <div class="tbl-wrap"><table>
      <tr><th>#</th><th>TEAM MEMBER</th><th>RUNS</th><th>AVG</th><th>BEST</th></tr>
      ${d.receiving_by_person.length
        ? d.receiving_by_person.map((r,i)=>`<tr>
            <td class="rank">${i===0?'🥇':i===1?'🥈':i===2?'🥉':i+1}</td>
            <td>${esc(r.processed_by)}</td>
            <td>${r.runs}</td>
            <td>${mins(r.avg_mins)}</td>
            <td style="color:var(--ok)">${mins(r.best_mins)}</td>
          </tr>`).join('')
        : '<tr><td colspan="5" style="color:#444;text-align:center;padding:20px">NO DATA YET</td></tr>'}
    </table></div>
  </div>`;
  html += `</div>`;
  html += `<div class="section" id="sec-tgp-cold-chain">
    <div class="section-title">TGP COLD CHAIN — ${esc(rangeLabel)}
      <span style="float:right;display:flex;gap:8px;flex-wrap:wrap">
        <button type="button" class="btn" onclick="printTgpColdChain('print')">PRINT COLD CHAIN</button>
        <button type="button" class="btn" onclick="printTgpColdChain('csv')">CSV</button>
      </span>
    </div>
    <p style="font-size:0.75rem;color:#888;text-transform:none;margin:0 0 12px">Pallet license plates and temperatures logged at TGP receiving. Out-of-range rows are flagged for vendor credit conversations — no floor tasks are auto-created.</p>
    <div class="tbl-wrap"><table>
      <tr><th>DATE</th><th>PLATE</th><th>DEPT ID</th><th>DEPARTMENT</th><th>TEMP °C</th><th>RANGE</th><th>INVOICE</th><th>BY</th></tr>
      ${(d.tgp_cold_chain || []).length
        ? d.tgp_cold_chain.map((r) => `<tr${Number(r.in_range) === 0 ? ' style="background:rgba(255,68,68,0.08)"' : ''}>
            <td style="font-size:0.72rem">${esc(r.store_date || '')}</td>
            <td style="color:var(--white);font-weight:700">${esc(r.license_plate || '')}</td>
            <td style="font-size:0.72rem;color:var(--text)">${esc(r.department || '')}</td>
            <td>${esc(r.department_label || r.department || '')}</td>
            <td>${esc(r.temp_c ?? '')}</td>
            <td>${Number(r.in_range) === 0 ? '<span class="pill" style="border-color:var(--danger);color:var(--danger)">OUT</span>' : '<span class="pill" style="border-color:var(--ok);color:var(--ok)">OK</span>'}</td>
            <td>${esc(r.invoice_ref || '')}</td>
            <td>${esc(r.captured_by || '')}</td>
          </tr>`).join('')
        : '<tr><td colspan="8" style="color:#444;text-align:center;padding:20px">NO TGP PALLET LOGS IN THIS RANGE</td></tr>'}
    </table></div>
  </div>`;
  html += `<div class="section" id="sec-safety-inspections">
    <div class="section-title">SAFETY INSPECTIONS — ${esc(rangeLabel)}</div>
    <p style="font-size:0.75rem;color:#888;text-transform:none;margin:0 0 12px">Submitted monthly committee walk-throughs from <a href="/safe" style="color:var(--accent)">/safe</a>. Findings are logged for review — no tasks are auto-created.</p>
    <div class="tbl-wrap"><table>
      <tr><th>DATE</th><th>SUBMITTED</th><th>BY</th><th>FINDINGS (NO)</th><th>PRINT</th></tr>
      ${(d.safety_inspections || []).length
        ? d.safety_inspections.map((r) => `<tr>
            <td style="font-weight:700;color:var(--white)">${esc(r.inspection_date || '')}</td>
            <td style="font-size:0.72rem">${r.submitted_at ? esc(new Date(r.submitted_at).toLocaleString()) : '—'}</td>
            <td>${esc(r.submitted_by || '')}</td>
            <td>${Number(r.no_count) > 0 ? `<span class="pill" style="border-color:var(--danger);color:var(--danger)">${esc(r.no_count)}</span>` : '<span class="pill" style="border-color:var(--ok);color:var(--ok)">0</span>'}</td>
            <td><button type="button" class="pill" style="cursor:pointer;background:transparent" onclick="printSafetyInspection('${esc(r.run_id)}')">PRINT</button></td>
          </tr>`).join('')
        : '<tr><td colspan="5" style="color:#444;text-align:center;padding:20px">NO SUBMITTED INSPECTIONS IN THIS RANGE</td></tr>'}
    </table></div>
  </div>`;
  html += `<div class="section" id="sec-receiving-recent">
    <div class="section-title">RECENT RECEIVING RUNS</div>
    <div class="tbl-wrap"><table>
      <tr><th>VENDOR</th><th>BY</th><th>TIME</th><th>DATE</th></tr>
      ${d.receiving_recent.slice(0,15).length
        ? d.receiving_recent.slice(0,15).map(r=>`<tr>
            <td>${esc(r.vendor)}</td>
            <td style="color:var(--text)">${esc(r.processed_by)}</td>
            <td><span class="pill">${mins(r.duration_mins)}</span></td>
            <td style="font-size:0.72rem;color:var(--text)">${r.arrival_time ? new Date(r.arrival_time).toLocaleDateString() : '—'}</td>
          </tr>`).join('')
        : '<tr><td colspan="4" style="color:#444;text-align:center;padding:20px">NO RECENT RUNS</td></tr>'}
    </table></div>
  </div>`;
  html += `</div>`;

  html += buildDeliveriesSection(d, rangeLabel, deliveries);

  html += '</div>';
  return html;
}


// --- public/js/reports/assemble.js ---
function buildReportFooter(d) {
  return `<div style="text-align:center;padding:30px;font-size:0.7rem;color:#333;letter-spacing:2px">
    ${esc((d && d.store && d.store.displayName) || 'TGP CENTER STORE')} (${esc((d && d.store && d.store.code) || '')}) — v${esc((d && d.appVersion) || '')} — REPORT GENERATED ${new Date().toLocaleString().toUpperCase()}
  </div>`;
}

function buildReport(d) {
  return buildTodayPanel(d) + buildLearnPanel(d) + buildHandoffPanel(d) + buildReportFooter(d);
}


// ── INIT ──────────────────────────────────────────────────────────────────────


export function configureReportsState(partial = {}) {
    if (partial.token !== undefined) token = partial.token;
    if (partial.viewDate !== undefined) viewDate = partial.viewDate;
    if (partial.viewStart !== undefined) viewStart = partial.viewStart;
    if (partial.viewEnd !== undefined) viewEnd = partial.viewEnd;
    if (partial.activeBackup !== undefined) activeBackup = partial.activeBackup;
    if (partial.reportMode !== undefined) reportMode = partial.reportMode;
}

export {
    buildReport,
    buildExecStrip,
    buildReportModeChrome,
    applyReportMode,
    actionInboxCount,
    isOrderDayActive,
    PRINT_SECTIONS,
    PRINT_PRESETS,
    openPrintSectionPicker,
    closePrintSectionPicker,
    confirmPrintSelected,
    applyPrintPreset,
    ackReportAction,
    deferRhythmFromReport,
    applyRhythmEstimate,
    addRhythmFromReport,
    applyViewDate,
};
